bool readBitDoubleWithinBody(dwgBuffer *buf, DRW::Version version,
                             std::uint32_t objSize, double& value) {
    if (!dictionaryBitRangeAvailable(buf, version, objSize, 2))
        return false;

    dwgBuffer rangeProbe = buf->forkIndependent();
    const std::uint8_t code = rangeProbe.get2Bits();
    const std::uint64_t payloadBits = code == 0 ? 64u : 0u;
    if (!rangeProbe.isGood()
        || !dictionaryBitRangeAvailable(&rangeProbe, version, objSize,
                                        payloadBits))
        return false;

    dwgBuffer probe = buf->forkIndependent();
    const double parsedValue = probe.getBitDouble();
    if (!probe.isGood() || !std::isfinite(parsedValue))
        return false;
    value = parsedValue;
    *buf = probe;
    return true;
}

bool read3BitDoubleWithinBody(dwgBuffer *buf, DRW::Version version,
                              std::uint32_t objSize, DRW_Coord& value) {
    if (!dictionaryBitRangeAvailable(buf, version, objSize, 2))
        return false;

    dwgBuffer probe = buf->forkIndependent();
    const DRW_Coord parsedValue = probe.get3BitDouble();
    if (!probe.isGood()
        || !std::isfinite(parsedValue.x)
        || !std::isfinite(parsedValue.y)
        || !std::isfinite(parsedValue.z)
        || !objectBodyFitsSize(currentObjectDwgBit(&probe), objSize))
        return false;
    value = parsedValue;
    *buf = probe;
    return true;
}

