bool DRW_PointPath::parseCode(int code,
                              const std::unique_ptr<dxfReader>& reader) {
    switch (code) {
    case 90:
        if (m_seen90++ != 0)
            return false;
        m_classVersion = reader->getInt32();
        return true;
    case 10:
        if (m_seen10++ != 0)
            return false;
        m_point.x = reader->getDouble();
        return true;
    case 20:
        if (m_seen10 != 1)
            return false;
        m_point.y = reader->getDouble();
        return true;
    case 30:
        if (m_seen10 != 1)
            return false;
        m_point.z = reader->getDouble();
        return true;
    default:
        return DRW_TableEntry::parseCode(code, reader);
    }
}

void DRW_PointPath::reset() {
    DRW_TableEntry::reset();
    tType = DRW::POINTPATH;
    m_classVersion = 0;
    m_point = DRW_Coord{};
    m_seen90 = 0;
    m_seen10 = 0;
}

bool DRW_PointPath::parseDwg(DRW::Version version, dwgBuffer *buf,
                             std::uint32_t bs) {
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    reset();
    if (buf == nullptr || version < DRW::AC1015)
        return false;
    try {

    dwgBuffer stringBuffer = *buf;
    if (!DRW_TableEntry::parseDwg(version, buf, &stringBuffer, bs))
        return fail();

    dwgBuffer bodyBuffer = *buf;
    dwgBuffer *bodyBuf = version > DRW::AC1018 ? &bodyBuffer : buf;

    std::uint32_t bodyEnd = objSize;
    std::uint32_t stringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!stringBuffer.getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(&stringBuffer) != stringStartBit)
            return fail();
        bodyEnd = static_cast<std::uint32_t>(stringStartBit);
        stringEnd = static_cast<std::uint32_t>(stringEndBit);
    }

    std::int32_t classVersion = 0;
    DRW_Coord point;
    if (!readBitShortWithinBody(bodyBuf, version, bodyEnd, classVersion)
        || !read3BitDoubleWithinBody(bodyBuf, version, bodyEnd, point)
        || !std::isfinite(point.x)
        || !std::isfinite(point.y)
        || !std::isfinite(point.z)
        || !bodyBuf->isGood() || !stringBuffer.isGood()
        || !objectBodyFitsSize(currentObjectDwgBit(bodyBuf), bodyEnd)
        || !objectBodyFitsSize(currentObjectDwgBit(&stringBuffer), stringEnd))
        return fail();

    dwgBuffer handleBuffer = *buf;
    dwgBuffer *handleBuf = version > DRW::AC1018 ? &handleBuffer : buf;
    seekObjectHandleStream(version, handleBuf, objSize);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!this->readDwgObjectCommonHandles(version, handleBuf, &parsedParentHandle, &parsedReactors, &parsedXDictHandle))
        return fail();

    m_classVersion = static_cast<std::int32_t>(classVersion);
    m_point = point;
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return buf->isGood() && stringBuffer.isGood() && handleBuf->isGood()
        ? true : fail();
    } catch (...) {
        return fail();
    }
}

bool DRW_PointPath::encodeDwg(DRW::Version version, dwgBufferW *buf,
                              dwgBufferW *strBuf,
                              dwgBufferW *handleBuf) const {
    (void)strBuf;
    const auto finiteCoord = [](const DRW_Coord& point) {
        return std::isfinite(point.x) && std::isfinite(point.y)
            && std::isfinite(point.z);
    };
    if (buf == nullptr || version < DRW::AC1015
        || m_classVersion < 0
        || m_classVersion > std::numeric_limits<std::uint16_t>::max()
        || !finiteCoord(m_point)
        || reactorHandles.size() > dwgSafety::MaxReactorCount
        || extensionDictionaryFlag() > 1)
        return false;

    dwgBufferW *hb = handleBuf != nullptr && version > DRW::AC1014
        ? handleBuf : buf;
    buf->putBitShort(static_cast<std::uint16_t>(m_classVersion));
    buf->put3BitDouble(m_point);
    const std::uint8_t effectiveXDictFlag = version > DRW::AC1015
        ? extensionDictionaryFlag() : 0;
    putCommonObjectHandlePrefix(
        hb, static_cast<std::uint32_t>(parentHandle),
        static_cast<std::int32_t>(reactorHandles.size()),
        effectiveXDictFlag, &reactorHandles, xDictHandle);
    return buf->isGood() && hb->isGood();
}

