// Dynamic-block object body decode.  Layout per libreDWG dwg2.spec
// (AcDbEvalExpr_fields / AcDbBlockElement_fields / AcDbBlockParameter_fields /
// AcDbBlockAction_fields / BLOCKVISIBILITYPARAMETER / verified
// BLOCK*ACTION subclasses),
// ground-truthed against dwgread -O JSON.  Handle-reference vectors (deps /
// blocks / params) live in the handle stream: their COUNT is read inline in
// the data stream, then the handles are decoded after common handles.  Every
// read is isGood()-guarded and every count is bounded.  A short body still
// degrades to the raw shelf; a short declared handle stream is structural and
// fails the typed parse transactionally.
bool DRW_DynamicBlockObject::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs){
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr)
        return fail();
    try {
    reset();
    dwgBuffer sBuff = *buf;
    dwgBuffer *sBuf = version > DRW::AC1018 ? &sBuff : buf;   // 2007+ string stream
    bool ret = DRW_TableEntry::parseDwg(version, buf, sBuf, bs);
    DRW_DBG("\n***************************** parsing DynamicBlock shell ****************\n");
    if (!ret)
        return fail();

    // For R2007+ the data cursor must stop at the beginning of the detached
    // string stream. A missing string stream is represented by the cursor at
    // objSize, so it does not have a footer to subtract.
    std::uint32_t dynamicBodyEnd = objSize;
    std::uint32_t dynamicStringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!sBuf->getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(sBuf) != stringStartBit)
            return fail();
        dynamicBodyEnd = static_cast<std::uint32_t>(stringStartBit);
        dynamicStringEnd = static_cast<std::uint32_t>(stringEndBit);
    }
    if (dynamicBodyEnd == 0)
        return fail();

    const auto bodyFits = [buf, sBuf, dynamicBodyEnd, dynamicStringEnd]() {
        return objectBodyFitsSize(currentObjectDwgBit(buf), dynamicBodyEnd)
            && objectBodyFitsSize(currentObjectDwgBit(sBuf), dynamicStringEnd);
    };
    if (!bodyFits())
        return fail();

    const auto readDynamicTextWithinBounds =
        [version, dynamicBodyEnd, dynamicStringEnd](
            dwgBuffer *bodyBuffer, dwgBuffer *stringBuffer,
            UTF8STRING& value) {
            return readVariableTextWithinBounds(
                bodyBuffer, stringBuffer, version, dynamicBodyEnd,
                version > DRW::AC1018 ? dynamicStringEnd : dynamicBodyEnd,
                value);
        };

    // Common + object-specific handles live in the handle stream; read a copy so
    // the data-stream walk is unaffected.  This also positions hBuff for the rare
    // evalexpr value_code==91 handle case.  Seek hBuff to objSize explicitly for
    // BOTH versions (not seekObjectHandleStream, which is a no-op for <=AC1018):
    // the body here is decoded only partially (Bare early-return, deferred handle
    // vectors), so buf never reaches the handle stream on its own, and the no-op
    // seek would leave hBuff at body-start -> garbage owner/reactor handles on
    // R2000/R2004. objSize is the handle-stream bit offset at every version
    // (same technique as the ACAD_TABLE <=AC1018 fix).
    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    if (!hBuff.setPosition(objSize >> 3)) {
        return fail();
    }
    hBuff.setBitPos(objSize & 7);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                 &parsedParentHandle, &parsedReactors,
                                 &parsedXDictHandle, handleEndBit)) {
        return fail();
    }
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;

    const auto handleEntriesFit = [&hBuff, handleEndBit](std::uint64_t count) {
        std::uint64_t currentBit = 0;
        if (!objectCurrentBit(hBuff, currentBit) || currentBit > handleEndBit)
            return false;
        return count <= (handleEndBit - currentBit) / 8u;
    };
    const auto handleCountFits = [&handleEntriesFit](std::int32_t count) {
        return isValidAssocCount(count)
            && handleEntriesFit(static_cast<std::uint64_t>(count));
    };
    const auto readDynamicHandle = [handleEndBit](dwgBuffer *handleBuffer) {
        return readObjectHandleRef(handleBuffer, handleEndBit);
    };
    const auto readDynamicHandleTransactional =
        [handleEndBit](dwgBuffer *handleBuffer, std::uint32_t& value) {
            return readObjectHandleRefTransactional(handleBuffer, value,
                                                    handleEndBit);
        };

    if (m_kind == Kind::PurgePreventer) {
        // libreDWG dwg2.spec: AcDbDynamicBlockPurgePreventer contains a BS
        // flag followed by one code-5 block handle.  Decode on independent
        // cursors so a truncated body cannot publish partial metadata.
        dwgBuffer bodyProbe = *buf;
        dwgBuffer handleProbe = hBuff;
        std::int32_t purgeFlag = 0;
        dwgHandle blockHandle;
        if (!readBitShortWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                    purgeFlag)
            || purgeFlag < 0
            || purgeFlag > std::numeric_limits<std::uint16_t>::max()
            || !readBoundedObjectHandle(handleProbe, 0, false, blockHandle,
                                        handleEndBit)
            || blockHandle.code != 5
            || !bodyProbe.isGood() || !handleProbe.isGood())
            return fail();
        *buf = bodyProbe;
        m_purgeFlag = static_cast<std::uint16_t>(purgeFlag);
        m_purgeBlockHandle = blockHandle.ref;
        m_bodyFullyDecoded = true;
        return true;
    }

    // Bare classes: shell + handle only (leading unknown bits would misalign a
    // body walk); the raw shelf preserves the full byte image regardless.
    if (m_kind == Kind::Bare)
        return true;

    if (m_kind == Kind::ParameterDependencyBody) {
        // BLOCKPARAMDEPENDENCYBODY has a split body: the two version fields
        // and class version are in the data stream, while name is in the
        // R2007+ string stream. Decode both streams speculatively so a short
        // field cannot consume the footer or publish partial state.
        dwgBuffer bodyProbe = *buf;
        dwgBuffer stringProbe = *sBuf;
        const bool modernStrings = version > DRW::AC1018;
        const std::uint32_t bodyEnd = [&]() {
            if (!modernStrings)
                return objSize;
            std::uint32_t end = 0;
            return objectBodyDataEnd(version, &stringProbe, objSize, end)
                ? end : 0;
        }();
        if (modernStrings && bodyEnd == 0)
            return fail();

        std::int32_t adbVersion = 0;
        std::int32_t dimensionBaseVersion = 0;
        std::int32_t classVersion = 0;
        UTF8STRING dependencyName;
        dwgBuffer *textProbe = modernStrings ? &stringProbe : &bodyProbe;
        const std::uint32_t fieldEnd = modernStrings ? bodyEnd : objSize;
        if (!readBitShortWithinBody(&bodyProbe, version, fieldEnd,
                                    adbVersion)
            || !readBitShortWithinBody(&bodyProbe, version, fieldEnd,
                                       dimensionBaseVersion)
            || !readDynamicTextWithinBounds(&bodyProbe, textProbe,
                                            dependencyName)
            || !readBitShortWithinBody(&bodyProbe, version, fieldEnd,
                                       classVersion)
            || !bodyProbe.isGood() || !textProbe->isGood()
            || !objectBodyFitsSize(currentObjectDwgBit(&bodyProbe), fieldEnd)
            || (modernStrings
                && !objectBodyFitsSize(currentObjectDwgBit(textProbe),
                                       dynamicStringEnd)))
            return fail();

        *buf = bodyProbe;
        if (modernStrings)
            *sBuf = stringProbe;
        m_adbVersion = adbVersion;
        m_dimensionBaseVersion = dimensionBaseVersion;
        m_dependencyName = std::move(dependencyName);
        m_classVersion = classVersion;
        m_bodyFullyDecoded = true;
        return true;
    }

    // ---- AcDbEvalExpr prefix (every non-Bare class) --------------------------
    // Keep the prefix on independent cursors.  Besides preventing a malformed
    // value selector from consuming the next field, this makes the public
    // typed/raw admission decision atomic for all eval-expression classes.
    dwgBuffer bodyProbe = *buf;
    dwgBuffer stringProbe = *sBuf;
    dwgBuffer handleProbe = hBuff;
    const auto readDynamicPrefixText = [&](UTF8STRING& value) {
        if (version > DRW::AC1018)
            return readDynamicTextWithinBounds(
                &bodyProbe, &stringProbe, value);
        return readDynamicTextWithinBounds(&bodyProbe, &bodyProbe, value);
    };
    std::int32_t parentId = 0;
    std::int32_t major = 0;
    std::int32_t minor = 0;
    std::int32_t valueCode = 0;
    std::int32_t nodeId = 0;
    std::uint32_t valueHandle = 0;
    UTF8STRING valueText;
    if (!readBitLongWithinBody(&bodyProbe, version, dynamicBodyEnd, parentId)
        || !readBitLongWithinBody(&bodyProbe, version, dynamicBodyEnd, major)
        || !readBitLongWithinBody(&bodyProbe, version, dynamicBodyEnd, minor)
        || !readSBitShortWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                    valueCode))
        return fail();

    switch (valueCode) { // value-code switch
    case 40: {
        double value = 0.0;
        if (!readBitDoubleWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                     value))
            return fail();
        break;
    }
    case 10:
    case 11: {
        DRW_Coord value;
        if (!read2RawDoubleWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                      value))
            return fail();
        break;
    }
    case 1:
        if (!readDynamicPrefixText(valueText))
            return fail();
        break;
    case 90: {
        std::int32_t value = 0;
        if (!readBitLongWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                   value))
            return fail();
        break;
    }
    case 91:
        // The value is a handle in the deferred object handle stream.  Keep it
        // typed, and fail the shell if the stream is truncated.
        if (!readDynamicHandleTransactional(&handleProbe, valueHandle))
            return fail();
        break;
    case 70: {
        std::int32_t value = 0;
        if (!readBitShortWithinBody(&bodyProbe, version, dynamicBodyEnd,
                                    value))
            return fail();
        break;
    }
    default:
        break;
    }
    if (!readBitLongWithinBody(&bodyProbe, version, dynamicBodyEnd, nodeId))
        return fail();
    if (!bodyProbe.isGood() || !stringProbe.isGood()
        || !handleProbe.isGood())
        return fail();

    *buf = bodyProbe;
    if (version > DRW::AC1018)
        *sBuf = stringProbe;
    hBuff = handleProbe;
    m_parentId = static_cast<std::uint32_t>(parentId);
    m_major = static_cast<std::uint32_t>(major);
    m_minor = static_cast<std::uint32_t>(minor);
    m_valueCode = static_cast<std::int16_t>(valueCode);
    m_valueHandle = valueHandle;
    m_nodeId = static_cast<std::uint32_t>(nodeId);
    m_evalExprParsed = true;

    if (m_kind == Kind::EvalExprOnly)
        return true;

    if (m_kind == Kind::GripLocationComponent) {
        // AcDbBlockGripExpr: grip_type BL(91) + grip_expr T(300).
        dwgBuffer gripBodyProbe = *buf;
        dwgBuffer gripStringProbe = *sBuf;
        std::int32_t gripType = 0;
        UTF8STRING gripExpr;
        if (!readBitLongWithinBody(&gripBodyProbe, version, dynamicBodyEnd,
                                   gripType)
            || !readDynamicTextWithinBounds(
                &gripBodyProbe, version > DRW::AC1018
                    ? &gripStringProbe : &gripBodyProbe,
                gripExpr))
            return fail();
        *buf = gripBodyProbe;
        if (version > DRW::AC1018)
            *sBuf = gripStringProbe;
        m_gripType = gripType;
        m_gripExpr = std::move(gripExpr);
        return true;
    }

    // ---- AcDbBlockElement prefix (grip / parameter / action classes) ---------
    dwgBuffer elementBodyProbe = *buf;
    dwgBuffer elementStringProbe = *sBuf;
    UTF8STRING elementName;
    std::int32_t elementMajor = 0;
    std::int32_t elementMinor = 0;
    std::int32_t eed1071 = 0;
    dwgBuffer *elementTextProbe = version > DRW::AC1018
        ? &elementStringProbe : &elementBodyProbe;
    if (!readDynamicTextWithinBounds(
            &elementBodyProbe, elementTextProbe, elementName)
        || !readBitLongWithinBody(&elementBodyProbe, version, dynamicBodyEnd,
                                  elementMajor)
        || !readBitLongWithinBody(&elementBodyProbe, version, dynamicBodyEnd,
                                  elementMinor)
        || !readBitLongWithinBody(&elementBodyProbe, version, dynamicBodyEnd,
                                  eed1071))
        return fail();
    if (!elementBodyProbe.isGood() || !elementStringProbe.isGood()
        || !bodyFits())
        return fail();
    *buf = elementBodyProbe;
    if (version > DRW::AC1018)
        *sBuf = elementStringProbe;
    m_elementName = std::move(elementName);
    m_elementMajor = static_cast<std::uint32_t>(elementMajor);
    m_elementMinor = static_cast<std::uint32_t>(elementMinor);
    m_eed1071 = eed1071;
    m_elementParsed = true;

    // AcDbBlockGrip body.  Most grips stop after the common body; linear and
    // alignment grips add orientation, while flip grips add combined state and
    // orientation.  The class name selects the suffix without consuming bits
    // from rotation, visibility, polar, or XY grips.
    if (m_kind == Kind::Grip) {
        dwgBuffer gripProbe = *buf;
        std::int32_t gripValue91 = 0;
        std::int32_t gripValue92 = 0;
        DRW_Coord gripLocation;
        bool gripValue280 = false;
        std::int32_t gripValue93 = 0;
        if (!readBitLongWithinBody(&gripProbe, version, dynamicBodyEnd,
                                   gripValue91)
            || !readBitLongWithinBody(&gripProbe, version, dynamicBodyEnd,
                                      gripValue92)
            || !read3BitDoubleWithinBody(&gripProbe, version, dynamicBodyEnd,
                                         gripLocation)
            || !readBitWithinBody(&gripProbe, version, dynamicBodyEnd,
                                  gripValue280)
            || !readBitLongWithinBody(&gripProbe, version, dynamicBodyEnd,
                                      gripValue93))
            return fail();
        std::int32_t gripCombinedState = 0;
        bool gripHasOrientation = false;
        DRW_Coord gripOrientation;
        if (m_recordName == "BLOCKFLIPGRIP") {
            if (!readBitLongWithinBody(&gripProbe, version, dynamicBodyEnd,
                                       gripCombinedState))
                return fail();
            gripHasOrientation = true;
        } else if (m_recordName == "BLOCKLINEARGRIP"
                   || m_recordName == "BLOCKALIGNMENTGRIP") {
            gripHasOrientation = true;
        }
        if (gripHasOrientation
            && !read3BitDoubleWithinBody(&gripProbe, version, dynamicBodyEnd,
                                          gripOrientation))
            return fail();
        *buf = gripProbe;
        m_gripValue91 = gripValue91;
        m_gripValue92 = gripValue92;
        m_gripLocation = gripLocation;
        m_gripValue280 = gripValue280;
        m_gripValue93 = gripValue93;
        m_gripCombinedState = gripCombinedState;
        m_gripHasOrientation = gripHasOrientation;
        m_gripOrientation = gripOrientation;
        m_bodyFullyDecoded = buf->isGood() && sBuf->isGood()
            && hBuff.isGood() && bodyFits();
        return m_bodyFullyDecoded;
    }

    // AcDbBlockAction classes extend AcDbBlockElement DIRECTLY (no
    // AcDbBlockParameter bits) — display_location follows element immediately.
    if (m_kind == Kind::Action || m_kind == Kind::MoveAction
        || m_kind == Kind::ScaleAction || m_kind == Kind::StretchAction
        || m_kind == Kind::FlipAction || m_kind == Kind::RotateAction
        || m_kind == Kind::ArrayAction || m_kind == Kind::LookupAction
        || m_kind == Kind::PolarStretchAction) {
        // Prefix-only for a plain action; the full body is decoded for the
        // action subclasses with verified layouts below.
        if (m_kind == Kind::Action)
            return true;
        // AcDbBlockAction: display_location 3BD, num_deps BL, dependency
        // handles (deferred), num_actions BL, and action indexes BL[].
        dwgBuffer actionProbe = *buf;
        DRW_Coord displayLocation;
        std::int32_t dependencyCount = 0;
        std::int32_t actionCount = 0;
        if (!read3BitDoubleWithinBody(&actionProbe, version, dynamicBodyEnd,
                                      displayLocation)
            || !readBitLongWithinBody(&actionProbe, version, dynamicBodyEnd,
                                      dependencyCount)
            || !isValidAssocCount(dependencyCount)
            || !handleCountFits(dependencyCount)
            || !readBitLongWithinBody(&actionProbe, version, dynamicBodyEnd,
                                      actionCount)
            || !isValidAssocCount(actionCount)
            || !countFitsObjectBody(&actionProbe, version, dynamicBodyEnd,
                                    actionCount, 2u))
            return fail();
        std::vector<std::int32_t> actionIndexes;
        if (!DRW::reserve(actionIndexes, actionCount))
            return fail();
        for (std::int32_t a = 0; a < actionCount; ++a) {
            std::int32_t actionIndex = 0;
            if (!readBitLongWithinBody(&actionProbe, version, dynamicBodyEnd,
                                       actionIndex))
                return fail();
            actionIndexes.push_back(actionIndex);
        }
        *buf = actionProbe;
        m_displayLocation = displayLocation;
        m_dependencyCount = dependencyCount;
        m_actionCount = actionCount;
        m_actionIndexes = std::move(actionIndexes);
        const auto readActionText = [buf, sBuf, version, &readDynamicTextWithinBounds](
                                         UTF8STRING& value) {
            if (version > DRW::AC1018)
                return readDynamicTextWithinBounds(buf, sBuf, value);
            return readDynamicTextWithinBounds(buf, buf, value);
        };
        auto readConnection = [buf, version, dynamicBodyEnd,
                               &readActionText](
                                  std::vector<std::int32_t>& codes,
                                  std::vector<UTF8STRING>& names) {
            std::int32_t code = 0;
            UTF8STRING name;
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, code)
                || !readActionText(name))
                return false;
            codes.push_back(code); // BL code
            names.push_back(std::move(name)); // T name
            return true;
        };
        if (m_kind == Kind::FlipAction) {
            // AcDbBlockFlipAction: four code/name connection points.
            for (int cp = 0; cp < 4; ++cp) {
                if (!readConnection(m_connectionCodes, m_connectionNames))
                    return fail();
            }
        } else if (m_kind == Kind::RotateAction) {
            // AcDbBlockActionWithBasePt followed by the rotation connection.
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_rotateActionOffset))
                return fail();
            for (int cp = 0; cp < 2; ++cp) {
                if (!readConnection(m_rotateBaseConnectionCodes,
                                    m_rotateBaseConnectionNames))
                    return fail();
            }
            if (!readBitWithinBody(buf, version, dynamicBodyEnd,
                                   m_rotateActionDependent)
                || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                             m_rotateActionBasePoint)
                || !readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                          m_rotateConnectionCode)
                || !readActionText(m_rotateConnectionName))
                return fail();
        } else if (m_kind == Kind::ArrayAction) {
            for (int cp = 0; cp < 4; ++cp) {
                if (!readConnection(m_connectionCodes, m_connectionNames))
                    return fail();
            }
            if (!readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                         m_arrayColumnOffset)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_arrayRowOffset))
                return fail();
        } else if (m_kind == Kind::LookupAction) {
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_lookupRowCount)
                || !readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                          m_lookupColumnCount)
                || !isValidAssocCount(m_lookupRowCount)
                || !isValidAssocCount(m_lookupColumnCount))
                return fail();
            const std::uint64_t entryCount =
                static_cast<std::uint64_t>(m_lookupRowCount)
                * static_cast<std::uint64_t>(m_lookupColumnCount);
            if (entryCount > static_cast<std::uint64_t>(kMaxAssocItems))
                return fail();
            if (!countFitsObjectBody(
                    buf, version, dynamicBodyEnd,
                    static_cast<std::int32_t>(entryCount), 8u))
                return fail();
            if (!DRW::reserve(m_lookupExpressions,
                              static_cast<int>(entryCount))
                || !DRW::reserve(m_lookupConnectionCodes,
                                 static_cast<int>(entryCount))
                || !DRW::reserve(m_lookupConnectionNames,
                                 static_cast<int>(entryCount))
                || !DRW::reserve(m_lookupEntryFlags282,
                                 static_cast<int>(entryCount))
                || !DRW::reserve(m_lookupEntryFlags281,
                                 static_cast<int>(entryCount)))
                return fail();
            for (std::uint64_t entry = 0;
                 entry < entryCount; ++entry) {
                UTF8STRING expression;
                if (!readActionText(expression))
                    return fail();
                m_lookupExpressions.push_back(std::move(expression));
                std::vector<std::int32_t> codes;
                std::vector<UTF8STRING> names;
                codes.reserve(3);
                names.reserve(3);
                for (int cp = 0; cp < 3; ++cp) {
                    if (!readConnection(codes, names))
                        return fail();
                }
                m_lookupConnectionCodes.push_back(std::move(codes));
                m_lookupConnectionNames.push_back(std::move(names));
                bool flag282 = false;
                bool flag281 = false;
                if (!readBitWithinBody(buf, version, dynamicBodyEnd, flag282)
                    || !readBitWithinBody(buf, version, dynamicBodyEnd,
                                          flag281))
                    return fail();
                m_lookupEntryFlags282.push_back(flag282);
                m_lookupEntryFlags281.push_back(flag281);
            }
            if (!readBitWithinBody(buf, version, dynamicBodyEnd,
                                  m_lookupFlag280))
                return fail();
        } else if (m_kind == Kind::PolarStretchAction) {
            for (int cp = 0; cp < 6; ++cp) {
                if (!readConnection(m_connectionCodes, m_connectionNames))
                    return fail();
            }
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_polarStretchPointCount)
                || !isValidAssocCount(m_polarStretchPointCount)
                || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                        m_polarStretchPointCount, 128u))
                return fail();
            if (!DRW::reserve(m_polarStretchPoints,
                              m_polarStretchPointCount))
                return fail();
            for (std::int32_t i = 0; i < m_polarStretchPointCount; ++i) {
                DRW_Coord point;
                if (!read2RawDoubleWithinBody(buf, version, dynamicBodyEnd,
                                              point))
                    return fail();
                m_polarStretchPoints.push_back(point);
            }
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_polarStretchHandleCount)
                || !isValidAssocCount(m_polarStretchHandleCount)
                || !handleEntriesFit(
                       static_cast<std::uint64_t>(m_dependencyCount)
                       + static_cast<std::uint64_t>(m_polarStretchHandleCount)))
                return fail();
            m_polarStretchHandles.clear();
            if (!DRW::reserve(m_polarStretchHandles,
                              m_polarStretchHandleCount)
                || !DRW::reserve(m_polarStretchHandleShorts,
                                 m_polarStretchHandleCount))
                return fail();
            for (std::int32_t i = 0; i < m_polarStretchHandleCount; ++i)
                m_polarStretchHandles.push_back(0);
            for (std::int32_t i = 0; i < m_polarStretchHandleCount; ++i) {
                std::int32_t handleShort = 0;
                if (!readBitShortWithinBody(buf, version, dynamicBodyEnd,
                                            handleShort))
                    return fail();
                m_polarStretchHandleShorts.push_back(
                    static_cast<std::int16_t>(handleShort));
            }
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_polarStretchCodeCount)
                || !isValidAssocCount(m_polarStretchCodeCount)
                || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                        m_polarStretchCodeCount, 2u))
                return fail();
            if (!DRW::reserve(m_polarStretchCodes,
                              m_polarStretchCodeCount))
                return fail();
            for (std::int32_t i = 0; i < m_polarStretchCodeCount; ++i) {
                std::int32_t code = 0;
                if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                           code))
                    return fail();
                m_polarStretchCodes.push_back(code);
            }
        } else if (m_kind == Kind::ScaleAction) {
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_scaleOffset))              // 3BD offset
                return fail();
            for (int cp = 0; cp < 2; ++cp) {
                if (!readConnection(m_baseConnectionCodes,
                                    m_baseConnectionNames))
                    return fail();
            }
            if (!readBitWithinBody(buf, version, dynamicBodyEnd,
                                   m_scaleDependent)                 // B dependent
                || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                             m_scaleBasePoint))       // 3BD base point
                return fail();
            for (int cp = 0; cp < 3; ++cp) {
                if (!readConnection(m_scaleConnectionCodes,
                                    m_scaleConnectionNames))
                    return fail();
            }
        } else if (m_kind == Kind::StretchAction) {
            for (int cp = 0; cp < 2; ++cp) {
                if (!readConnection(m_connectionCodes, m_connectionNames))
                    return fail();
            }
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_stretchPointCount)              // BL points
                || !isValidAssocCount(m_stretchPointCount)
                || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                        m_stretchPointCount, 128u))
                return fail();
            if (!DRW::reserve(m_stretchPoints, m_stretchPointCount))
                return fail();
            for (std::int32_t i = 0; i < m_stretchPointCount; ++i) {
                DRW_Coord point;
                if (!read2RawDoubleWithinBody(buf, version, dynamicBodyEnd,
                                              point))
                    return fail();
                m_stretchPoints.push_back(point);                 // 2RD point
            }

            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_handleReferenceCount)           // BL refs
                || !isValidAssocCount(m_handleReferenceCount)
                || !countFitsObjectBody(
                       buf, version, dynamicBodyEnd,
                       m_handleReferenceCount,
                       version <= DRW::AC1018 ? 10u : 2u))
                return fail();
            if (version > DRW::AC1018
                && !handleEntriesFit(
                       static_cast<std::uint64_t>(m_dependencyCount)
                       + static_cast<std::uint64_t>(m_handleReferenceCount)))
                return fail();
            if (!DRW::reserve(m_handleReferenceHandles,
                              m_handleReferenceCount)
                || !DRW::reserve(m_handleReferenceIndexCounts,
                                 m_handleReferenceCount)
                || !DRW::reserve(m_handleReferenceIndexes,
                                 m_handleReferenceCount))
                return fail();
            for (std::int32_t i = 0;
                 i < m_handleReferenceCount && buf->isGood(); ++i) {
                std::uint32_t ref = 0;
                if (version <= DRW::AC1018)
                    if (!readObjectHandleRefTransactional(buf, ref,
                                                          dynamicBodyEnd))
                        return fail();                            // inline legacy
                std::int32_t indexCount = 0;
                if (!readBitShortWithinBody(buf, version, dynamicBodyEnd,
                                            indexCount)
                    || !isValidAssocCount(indexCount)
                    || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                            indexCount, 2u))
                    return fail();
                std::vector<std::int32_t> indexes;
                if (!DRW::reserve(indexes, indexCount))
                    return fail();
                for (std::int32_t j = 0; j < indexCount; ++j) {
                    std::int32_t index = 0;
                    if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                               index))
                        return fail();
                    indexes.push_back(index);
                }
                m_handleReferenceHandles.push_back(ref);
                m_handleReferenceIndexCounts.push_back(indexCount);
                m_handleReferenceIndexes.push_back(std::move(indexes));
            }

            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       m_codeReferenceCount)             // BL codes
                || !isValidAssocCount(m_codeReferenceCount)
                || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                        m_codeReferenceCount, 4u))
                return fail();
            if (!DRW::reserve(m_codeReferenceCodes, m_codeReferenceCount)
                || !DRW::reserve(m_codeReferenceIndexCounts,
                                 m_codeReferenceCount)
                || !DRW::reserve(m_codeReferenceIndexes,
                                 m_codeReferenceCount))
                return fail();
            for (std::int32_t i = 0;
                 i < m_codeReferenceCount && buf->isGood(); ++i) {
                std::int32_t code = 0;
                std::int32_t indexCount = 0;
                if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                           code)
                    || !readBitShortWithinBody(buf, version, dynamicBodyEnd,
                                               indexCount)
                    || !isValidAssocCount(indexCount)
                    || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                            indexCount, 2u))
                    return fail();
                std::vector<std::int32_t> indexes;
                if (!DRW::reserve(indexes, indexCount))
                    return fail();
                for (std::int32_t j = 0; j < indexCount; ++j) {
                    std::int32_t index = 0;
                    if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                               index))
                        return fail();
                    indexes.push_back(index);
                }
                m_codeReferenceCodes.push_back(code);
                m_codeReferenceIndexCounts.push_back(indexCount);
                m_codeReferenceIndexes.push_back(std::move(indexes));
            }
            if (!readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                         m_actionOffsetX)              // BD (140)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_actionOffsetY))           // BD (141)
                return fail();
            m_angleOffset = 0.0;
            dwgBuffer angleProbe = buf->forkIndependent();
            double angleOffset = 0.0;
            if (readBitDoubleWithinBody(&angleProbe, version, dynamicBodyEnd,
                                        angleOffset)) {
                *buf = angleProbe;
                m_angleOffset = angleOffset;
            }
        } else {
            // AcDbBlockMoveAction: 2 connection points and three BD offsets.
            for (int cp = 0; cp < 2; ++cp) {
                if (!readConnection(m_connectionCodes, m_connectionNames))
                    return fail();
            }
            if (!readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                         m_actionOffsetX)                // BD (140)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_actionOffsetY))             // BD (141)
                return fail();
            m_angleOffset = 0.0;
            dwgBuffer angleProbe = buf->forkIndependent();
            double angleOffset = 0.0;
            if (readBitDoubleWithinBody(&angleProbe, version, dynamicBodyEnd,
                                        angleOffset)) {
                *buf = angleProbe;
                m_angleOffset = angleOffset;
            }
        }
        m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
        if (!m_bodyFullyDecoded)
            return true;
        dwgBuffer actionHandleProbe = hBuff;
        std::vector<std::uint32_t> dependencyHandles;
        if (!DRW::reserve(dependencyHandles, m_dependencyCount))
            return fail();
        for (std::int32_t i = 0; i < m_dependencyCount; ++i) {
            std::uint32_t ref = 0;
            if (!readDynamicHandleTransactional(&actionHandleProbe, ref))
                return fail();
            dependencyHandles.push_back(ref);
        }
        std::vector<std::uint32_t> handleReferenceHandles =
            m_handleReferenceHandles;
        if (m_kind == Kind::StretchAction && version > DRW::AC1018) {
            for (std::size_t i = 0; i < handleReferenceHandles.size(); ++i) {
                if (!readDynamicHandleTransactional(
                        &actionHandleProbe, handleReferenceHandles[i]))
                    return fail();
            }
        }
        std::vector<std::uint32_t> polarStretchHandles = m_polarStretchHandles;
        if (m_kind == Kind::PolarStretchAction) {
            for (std::size_t i = 0; i < polarStretchHandles.size(); ++i) {
                if (!readDynamicHandleTransactional(
                        &actionHandleProbe, polarStretchHandles[i]))
                    return fail();
            }
        }
        hBuff = actionHandleProbe;
        m_dependencyHandles = std::move(dependencyHandles);
        m_handleReferenceHandles = std::move(handleReferenceHandles);
        m_polarStretchHandles = std::move(polarStretchHandles);
        return true;
    }

    // AcDbBlockParameter: show_properties B(280) + chain_actions B(281).
    // (Parameter / VisibilityParameter both extend AcDbBlockParameter.)
    if (!readBitWithinBody(buf, version, dynamicBodyEnd, m_showProperties)
        || !readBitWithinBody(buf, version, dynamicBodyEnd, m_chainActions))
        return fail();

    const auto readDynamicText = [buf, sBuf, version,
                                  &readDynamicTextWithinBounds](
                                     UTF8STRING& value) {
        return readDynamicTextWithinBounds(
            buf, version > DRW::AC1018 ? sBuf : buf, value);
    };

    auto readPropertyInfo = [this, buf, sBuf, version, dynamicBodyEnd,
                             dynamicStringEnd,
                             &readDynamicText](
                                std::int32_t& count,
                                std::vector<std::int32_t>& codes,
                                std::vector<UTF8STRING>& names) {
        if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, count))
            return false;
        if (!isValidAssocCount(count))
            return false;
        const std::uint32_t minimumBodyBits = sBuf == buf ? 4u : 2u;
        if (!countFitsObjectBody(buf, version, dynamicBodyEnd, count,
                                 minimumBodyBits)
            || (sBuf != buf
                && !countFitsObjectBody(sBuf, version, dynamicStringEnd,
                                         count, 2u)))
            return false;
        codes.clear();
        names.clear();
        if (!DRW::reserve(codes, count)
            || !DRW::reserve(names, count))
            return false;
        for (std::int32_t i = 0; i < count && buf->isGood(); ++i) {
            std::int32_t code = 0;
            UTF8STRING name;
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, code)
                || !readDynamicText(name))
                return false;
            codes.push_back(code);
            names.push_back(std::move(name));
        }
        return buf->isGood() && sBuf->isGood();
    };

    auto readTwoPointBody = [buf, sBuf, version, dynamicBodyEnd,
                             dynamicStringEnd,
                             &readDynamicText, this]() {
        if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                      m_firstPoint)
            || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                         m_secondPoint))
            return false;
        for (std::size_t group = 0; group < m_twoPointPropertyCodes.size();
             ++group) {
            std::int32_t count = 0;
            if (!readBitShortWithinBody(buf, version, dynamicBodyEnd, count)
                || !isValidAssocCount(count))
                return false;
            const std::uint32_t minimumBodyBits = sBuf == buf ? 4u : 2u;
            if (!countFitsObjectBody(buf, version, dynamicBodyEnd, count,
                                     minimumBodyBits)
                || (sBuf != buf
                    && !countFitsObjectBody(sBuf, version, dynamicStringEnd,
                                            count,
                                            2u)))
                return false;
            auto& codes = m_twoPointPropertyCodes[group];
            auto& names = m_twoPointPropertyNames[group];
            codes.clear();
            names.clear();
            if (!DRW::reserve(codes, count)
                || !DRW::reserve(names, count))
                return false;
            for (std::int32_t i = 0; i < count && buf->isGood(); ++i) {
                std::int32_t code = 0;
                UTF8STRING name;
                if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, code)
                    || !readDynamicText(name))
                    return false;
                codes.push_back(code);
                names.push_back(std::move(name));
            }
        }
        for (auto& state : m_propertyStates) {
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, state))
                return false;
        }
        std::int32_t baseLocation = 0;
        if (!readBitShortWithinBody(buf, version, dynamicBodyEnd,
                                    baseLocation))
            return false;
        m_parameterBaseLocation = static_cast<std::int16_t>(baseLocation);
        return true;
    };

    auto readDynamicValueSet = [buf, version, dynamicBodyEnd](
                                   std::int32_t& flags, double& minimum,
                                   double& maximum, double& increment,
                                   std::uint16_t& declaredCount,
                                   std::vector<double>& values) {
        std::int32_t count = 0;
        if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, flags)
            || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                        minimum)
            || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                        maximum)
            || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                        increment)
            || !readBitShortWithinBody(buf, version, dynamicBodyEnd, count)
            || !isValidAssocCount(count, kMaxAssocValueParams)
            || !countFitsObjectBody(buf, version, dynamicBodyEnd, count, 2u))
            return false;

        std::vector<double> parsedValues;
        if (!DRW::reserve(parsedValues, count))
            return false;
        for (std::int32_t i = 0; i < count; ++i) {
            double value = 0.0;
            if (!readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                         value))
                return false;
            parsedValues.push_back(value);
        }
        declaredCount = static_cast<std::uint16_t>(count);
        values = std::move(parsedValues);
        return true;
    };

    if (m_kind == Kind::Parameter)
        return true;

    if (m_kind == Kind::BasePointParameter || m_kind == Kind::LookupParameter) {
        // The base-point/lookup variant uses the compact one-point prefix:
        // location, value170, value171, and value93.  It does not contain the
        // two property-info records used by BLOCKPOINTPARAMETER and visibility.
        std::int32_t value170 = 0;
        std::int32_t value171 = 0;
        if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                      m_defPoint)
            || !readBitShortWithinBody(buf, version, dynamicBodyEnd, value170)
            || !readBitShortWithinBody(buf, version, dynamicBodyEnd, value171)
            || !readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                      m_parameterValue93))
            return fail();
        m_parameterValue170 = static_cast<std::int16_t>(value170);
        m_parameterValue171 = static_cast<std::int16_t>(value171);

        if (m_kind == Kind::BasePointParameter) {
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_point)
                || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                             m_basePoint))
                return fail();
            m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
            return true;
        }

        if (!readBitLongWithinBody(buf, version, dynamicBodyEnd, m_lookupIndex)
            || !readDynamicText(m_lookupName)
            || !readDynamicText(m_lookupDescription)
            || !readDynamicText(m_lookupUnknownText))
            return fail();
        m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
        return true;
    }

    if (m_kind == Kind::PointParameter || m_kind == Kind::VisibilityParameter) {
        // AcDbBlock1PtParameter: def_pt 3BD + prop1/prop2 PropInfo +
        // num_propinfos.  The property-info count is metadata, while each
        // connection count is bounded because it controls a read loop.
        if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                      m_defPoint))
            return fail();
        if (!readPropertyInfo(m_propertyInfo1Count, m_propertyInfo1Codes,
                              m_propertyInfo1Names)
            || !readPropertyInfo(m_propertyInfo2Count, m_propertyInfo2Codes,
                                 m_propertyInfo2Names))
            return fail();
        if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                   m_propertyInfoCount)
            || !isValidAssocCount(m_propertyInfoCount))
            return fail();

        if (m_kind == Kind::PointParameter) {
            if (!readDynamicText(m_positionName)
                || !readDynamicText(m_positionDescription))
                return fail();
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_labelPoint))
                return fail();
            m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
            return true;
        }

        // AcDbBlockVisibilityParameter body.
        if (!readBitWithinBody(buf, version, dynamicBodyEnd,
                               m_isInitialized) // B is_initialized (281)
            || !readDynamicText(m_visibilityName) // T blockvisi_name (301)
            || !readDynamicText(m_visibilityDescription)) // T blockvisi_desc (302)
            return fail();
        if (!readBitWithinBody(buf, version, dynamicBodyEnd, m_unknownBool)
            || !readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                      m_blockCount)) // BL num_blocks (93)
            return fail();
        if (!handleCountFits(m_blockCount))
            return fail();
        if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                   m_stateCount) // BL num_states (92)
            || !isValidAssocCount(m_stateCount)
            || !countFitsObjectBody(buf, version, dynamicBodyEnd,
                                    m_stateCount, 4u)
                || (sBuf != buf
                    && !countFitsObjectBody(sBuf, version, dynamicStringEnd,
                                             m_stateCount, 2u)))
            return fail();
        m_stateNames.clear();
        if (!DRW::reserve(m_stateNames, m_stateCount))
            return fail();
        std::vector<std::int32_t> stateBlockCounts;
        std::vector<std::int32_t> stateParameterCounts;
        if (!DRW::reserve(stateBlockCounts, m_stateCount)
            || !DRW::reserve(stateParameterCounts, m_stateCount))
            return fail();
        for (std::int32_t s = 0; s < m_stateCount && buf->isGood(); ++s) {
            UTF8STRING stateName;
            if (!readDynamicText(stateName))
                return fail();
            m_stateNames.push_back(std::move(stateName)); // T name (303)
            std::int32_t stateBlocks = 0;
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       stateBlocks)) // BL num_blocks (94)
                return fail();
            std::int32_t stateParams = 0;
            if (!readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                       stateParams)) // BL num_params (95)
                return fail();
            if (!isValidAssocCount(stateBlocks)
                || !isValidAssocCount(stateParams))
                return fail();
            stateBlockCounts.push_back(stateBlocks);
            stateParameterCounts.push_back(stateParams);
        }
        m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
        if (!m_bodyFullyDecoded)
            return fail();

        auto readDeferredHandles = [&hBuff, handleEndBit,
                                    &readDynamicHandle](
                                       std::int32_t count,
                                       std::vector<std::uint32_t>& out) {
            std::uint64_t currentBit = 0;
            if (!isValidAssocCount(count)
                || !objectCurrentBit(hBuff, currentBit)
                || currentBit > handleEndBit
                || static_cast<std::uint64_t>(count)
                       > (handleEndBit - currentBit) / 8u)
                return false;
            out.clear();
            if (!DRW::reserve(out, count))
                return false;
            for (std::int32_t i = 0; i < count; ++i) {
                const std::uint32_t ref = readDynamicHandle(&hBuff);
                if (!hBuff.isGood())
                    return false;
                out.push_back(ref);
            }
            return true;
        };

        std::vector<std::uint32_t> blockHandles;
        if (!readDeferredHandles(m_blockCount, blockHandles)) {
            return fail();
        }
        std::vector<std::vector<std::uint32_t>> stateBlockHandles;
        std::vector<std::vector<std::uint32_t>> stateParameterHandles;
        if (!DRW::resize(stateBlockHandles,
                         static_cast<int>(stateBlockCounts.size()))
            || !DRW::resize(stateParameterHandles,
                            static_cast<int>(stateParameterCounts.size())))
            return fail();
        for (std::size_t i = 0; i < stateBlockCounts.size(); ++i) {
            if (!readDeferredHandles(stateBlockCounts[i], stateBlockHandles[i])
                || !readDeferredHandles(stateParameterCounts[i],
                                         stateParameterHandles[i])) {
                return fail();
            }
        }
        m_blockHandles = std::move(blockHandles);
        m_stateBlockHandles = std::move(stateBlockHandles);
        m_stateParameterHandles = std::move(stateParameterHandles);
        return true;
    }

    if (m_kind == Kind::FlipParameter || m_kind == Kind::RotationParameter
        || m_kind == Kind::LinearParameter || m_kind == Kind::PolarParameter
        || m_kind == Kind::AlignmentParameter || m_kind == Kind::XYParameter
        || m_kind == Kind::AlignedConstraintParameter
        || m_kind == Kind::HorizontalConstraintParameter
        || m_kind == Kind::VerticalConstraintParameter
        || m_kind == Kind::AngularConstraintParameter
        || m_kind == Kind::DiametricConstraintParameter
        || m_kind == Kind::RadialConstraintParameter) {
        if (!readTwoPointBody())
            return fail();

        if (m_kind == Kind::FlipParameter) {
            if (!readDynamicText(m_flipCaption)
                || !readDynamicText(m_flipDescription)
                || !readDynamicText(m_flipBaseStateName)
                || !readDynamicText(m_flipFlippedStateName)
                || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                             m_flipCaptionLocation)
                || !readDynamicText(m_flipTooltip)
                || !readBitLongWithinBody(buf, version, dynamicBodyEnd,
                                          m_flipValue96))
                return fail();
        } else if (m_kind == Kind::RotationParameter) {
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_rotationBaseAnglePoint)
                || !readDynamicText(m_rotationAngleName)
                || !readDynamicText(m_rotationAngleDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_rotationAngle)
                || !readDynamicValueSet(
                    m_rotationValueSetFlags, m_rotationMinimum,
                    m_rotationMaximum, m_rotationIncrement,
                    m_rotationDeclaredValueCount, m_rotationValues))
                return fail();
        } else if (m_kind == Kind::LinearParameter) {
            if (!readDynamicText(m_linearDistanceName)
                || !readDynamicText(m_linearDistanceDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_linearDistance)
                || !readDynamicValueSet(
                    m_linearValue96, m_linearValue141, m_linearValue142,
                    m_linearValue143, m_linearDeclaredValueCount,
                    m_linearValues))
                return fail();
        } else if (m_kind == Kind::PolarParameter) {
            if (!readDynamicText(m_polarAngleName)
                || !readDynamicText(m_polarAngleDescription)
                || !readDynamicText(m_polarDistanceName)
                || !readDynamicText(m_polarDistanceDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_polarOffset)
                || !readDynamicValueSet(
                    m_polarAngleValueSetFlags, m_polarAngleMinimum,
                    m_polarAngleMaximum, m_polarAngleIncrement,
                    m_polarAngleDeclaredValueCount, m_polarAngleValues)
                || !readDynamicValueSet(
                    m_polarDistanceValueSetFlags, m_polarDistanceMinimum,
                    m_polarDistanceMaximum, m_polarDistanceIncrement,
                    m_polarDistanceDeclaredValueCount,
                    m_polarDistanceValues))
                return fail();
        } else if (m_kind == Kind::XYParameter) {
            if (!readDynamicText(m_xyXLabel)
                || !readDynamicText(m_xyXDescription)
                || !readDynamicText(m_xyYLabel)
                || !readDynamicText(m_xyYDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_xyXValue)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_xyYValue)
                || !readDynamicValueSet(
                    m_xyXValueSetFlags, m_xyXMinimum, m_xyXMaximum,
                    m_xyXIncrement, m_xyXDeclaredValueCount, m_xyXValues)
                || !readDynamicValueSet(
                    m_xyYValueSetFlags, m_xyYMinimum, m_xyYMaximum,
                    m_xyYIncrement, m_xyYDeclaredValueCount, m_xyYValues))
                return fail();
        } else if (m_kind == Kind::AngularConstraintParameter) {
            if (!read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                          m_angularCenterPoint)
                || !read3BitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                             m_angularEndPoint)
                || !readDynamicText(m_constraintExpressionName)
                || !readDynamicText(m_constraintExpressionDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_constraintValue)
                || !readBitWithinBody(
                    buf, version, dynamicBodyEnd,
                    m_angularOrientationOnBothGrips)
                || !readDynamicValueSet(
                    m_constraintValueSetFlags, m_constraintMinimum,
                    m_constraintMaximum, m_constraintIncrement,
                    m_constraintDeclaredValueCount, m_constraintValues))
                return fail();
            if (version <= DRW::AC1018 || objSize == 0) {
                if (!readObjectHandleRefTransactional(
                        buf, m_constraintDependencyHandle, dynamicBodyEnd))
                    return fail();
            } else if (!readDynamicHandleTransactional(
                           &hBuff, m_constraintDependencyHandle)) {
                return fail();
            }
            m_bodyFullyDecoded = buf->isGood() && sBuf->isGood()
                && hBuff.isGood() && bodyFits();
            return true;
        } else if (m_kind == Kind::AlignedConstraintParameter
                   || m_kind == Kind::HorizontalConstraintParameter
                || m_kind == Kind::VerticalConstraintParameter
                   || m_kind == Kind::DiametricConstraintParameter
                   || m_kind == Kind::RadialConstraintParameter) {
            if (!readDynamicText(m_constraintExpressionName)
                || !readDynamicText(m_constraintExpressionDescription)
                || !readBitDoubleWithinBody(buf, version, dynamicBodyEnd,
                                            m_constraintValue)
                || !readDynamicValueSet(
                    m_constraintValueSetFlags, m_constraintMinimum,
                    m_constraintMaximum, m_constraintIncrement,
                    m_constraintDeclaredValueCount, m_constraintValues))
                return fail();
            // The spec places dependency after the constraint suffix.  In
            // legacy files it is inline here; R2007+ stores it in hBuff.
            if (version <= DRW::AC1018 || objSize == 0) {
                if (!readObjectHandleRefTransactional(
                        buf, m_constraintDependencyHandle, dynamicBodyEnd))
                    return fail();
            } else if (!readDynamicHandleTransactional(
                           &hBuff, m_constraintDependencyHandle)) {
                return fail();
            }
            m_bodyFullyDecoded = buf->isGood() && sBuf->isGood()
                && hBuff.isGood() && bodyFits();
            return true;
        } else {
            if (!readBitWithinBody(buf, version, dynamicBodyEnd,
                                   m_alignPerpendicular))
                return fail();
        }
        m_bodyFullyDecoded = buf->isGood() && sBuf->isGood() && bodyFits();
        return true;
    }

    return true;
    } catch (...) {
        return fail();
    }
}

void DRW_DetailViewStyle::reset() {
    tType = DRW::DETAILVIEWSTYLE;
    m_modelDoc = DRW_ModelDocViewStyle();
    m_classVersion = 0;
    m_flags = 0;
    m_identifierStyleHandle = 0;
    m_identifierColor = 256;
    m_identifierHeight = 0.0;
    m_identifierExcludeCharacters.clear();
    m_identifierOffset = 0.0;
    m_identifierPlacement = 0;
    m_arrowSymbolHandle = 0;
    m_arrowSymbolColor = 256;
    m_arrowSymbolSize = 0.0;
    m_boundaryLineTypeHandle = 0;
    m_boundaryLineWeight = 0;
    m_boundaryLineColor = 256;
    m_viewLabelTextStyleHandle = 0;
    m_viewLabelTextColor = 256;
    m_viewLabelTextHeight = 0.0;
    m_viewLabelAttachment = 0;
    m_viewLabelOffset = 0.0;
    m_viewLabelAlignment = 0;
    m_viewLabelPattern.clear();
    m_connectionLineTypeHandle = 0;
    m_connectionLineWeight = 0;
    m_connectionLineColor = 256;
    m_borderLineTypeHandle = 0;
    m_borderLineWeight = 0;
    m_borderLineColor = 256;
    m_modelEdge = 0;
    m_dxfSubclass.clear();
    m_dxfGroup = -1;
    m_dxfHandleCount = 0;
    m_dxfColorCount = 0;
    m_dxfDoubleCount = 0;
    m_dxfLongCount = 0;
    DRW_TableEntry::reset();
}

bool DRW_DetailViewStyle::parseCode(int code, const std::unique_ptr<dxfReader>& reader) {
    if (code == 100) {
        m_dxfSubclass = reader->getUtf8String();
        m_dxfGroup = -1;
        m_dxfHandleCount = m_dxfColorCount = m_dxfDoubleCount = m_dxfLongCount = 0;
        return true;
    }
    if (m_dxfSubclass == "AcDbModelDocViewStyle") {
        switch (code) {
        case 70: m_modelDoc.m_modelDocClassVersion = reader->getInt32(); return true;
        case 3:  m_modelDoc.m_description = reader->getUtf8String(); return true;
        case 290: m_modelDoc.m_modifiedForRecompute = reader->getBool(); return true;
        case 300: m_modelDoc.m_displayName = reader->getUtf8String(); return true;
        case 90: m_modelDoc.m_viewStyleFlags = static_cast<std::uint32_t>(reader->getInt32()); return true;
        default: return DRW_TableEntry::parseCode(code, reader);
        }
    }
    if (m_dxfSubclass != "AcDbDetailViewStyle")
        return DRW_TableEntry::parseCode(code, reader);

    if (code == 71) {
        m_dxfGroup = reader->getInt32();
        m_dxfHandleCount = m_dxfColorCount = m_dxfDoubleCount = m_dxfLongCount = 0;
        return true;
    }
    switch (code) {
    case 70:
        m_classVersion = reader->getInt32();
        return true;
    case 340: {
        const std::uint32_t ref = static_cast<std::uint32_t>(reader->getHandleString());
        if (m_dxfGroup == 1) {
            if (m_dxfHandleCount++ == 0) m_identifierStyleHandle = ref;
            else m_arrowSymbolHandle = ref;
        } else if (m_dxfGroup == 2) {
            m_boundaryLineTypeHandle = ref;
        } else if (m_dxfGroup == 3) {
            m_viewLabelTextStyleHandle = ref;
        } else if (m_dxfGroup == 4) {
            if (m_dxfHandleCount++ == 0) m_connectionLineTypeHandle = ref;
            else m_borderLineTypeHandle = ref;
        }
        return true;
    }
    case 62: {
        const int color = reader->getInt32();
        if (m_dxfGroup == 1) {
            if (m_dxfColorCount++ == 0) m_identifierColor = color;
            else m_arrowSymbolColor = color;
        } else if (m_dxfGroup == 2) {
            m_boundaryLineColor = color;
        } else if (m_dxfGroup == 3) {
            m_viewLabelTextColor = color;
        } else if (m_dxfGroup == 4) {
            if (m_dxfColorCount++ == 0) m_connectionLineColor = color;
            else m_borderLineColor = color;
        }
        return true;
    }
    case 40: {
        const double value = reader->getDouble();
        if (m_dxfGroup == 1) {
            if (m_dxfDoubleCount == 0) m_identifierHeight = value;
            else if (m_dxfDoubleCount == 1) m_arrowSymbolSize = value;
            else m_identifierOffset = value;
            ++m_dxfDoubleCount;
        } else if (m_dxfGroup == 3) {
            if (m_dxfDoubleCount++ == 0) m_viewLabelTextHeight = value;
            else m_viewLabelOffset = value;
        }
        return true;
    }
    case 90: {
        const std::int32_t value = reader->getInt32();
        if (m_dxfGroup == 0 || m_dxfGroup == -1) m_flags = static_cast<std::uint32_t>(value);
        else if (m_dxfGroup == 2) m_boundaryLineWeight = value;
        else if (m_dxfGroup == 3) {
            if (m_dxfLongCount++ == 0) m_viewLabelAttachment = static_cast<std::uint32_t>(value);
            else m_viewLabelAlignment = static_cast<std::uint32_t>(value);
        } else if (m_dxfGroup == 4) {
            if (m_dxfLongCount++ == 0) m_connectionLineWeight = value;
            else m_borderLineWeight = value;
        }
        return true;
    }
    case 280:
        if (m_dxfGroup == 1 || m_dxfGroup == 4) {
            const int value = reader->getInt32();
            if (value < 0 || value > std::numeric_limits<std::uint8_t>::max())
                return false;
            if (m_dxfGroup == 1)
                m_identifierPlacement = static_cast<std::uint8_t>(value);
            else
                m_modelEdge = static_cast<std::uint8_t>(value);
        } else {
            reader->getInt32();
        }
        return true;
    case 300:
        if (m_dxfGroup == 1) m_identifierExcludeCharacters = reader->getUtf8String();
        else if (m_dxfGroup == 3) m_viewLabelPattern = reader->getUtf8String();
        else reader->getUtf8String();
        return true;
    default:
        return DRW_TableEntry::parseCode(code, reader);
    }
}

bool DRW_DetailViewStyle::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs) {
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr) {
        reset();
        return false;
    }
    try {
    reset();
    dwgBuffer sBuff = *buf;
    dwgBuffer *sBuf = version > DRW::AC1018 ? &sBuff : buf;
    bool ret = DRW_TableEntry::parseDwg(version, buf, sBuf, bs);
    DRW_DBG("\n***************************** parsing DETAILVIEWSTYLE ******************\n");
    if (!ret) return fail();

    std::uint32_t bodyEnd = objSize;
    std::uint32_t stringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!sBuf->getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(sBuf) != stringStartBit)
            return fail();
        bodyEnd = static_cast<std::uint32_t>(stringStartBit);
        stringEnd = static_cast<std::uint32_t>(stringEndBit);
    }
    const auto bodyFits = [buf, sBuf, bodyEnd, stringEnd]() {
        return objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd)
            && objectBodyFitsSize(currentObjectDwgBit(sBuf), stringEnd);
    };
    if (!bodyFits())
        return fail();

    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();

    const auto readText = [version, buf, sBuf, bodyEnd, stringEnd](
                              UTF8STRING& value) {
        return readVariableTextWithinBounds(buf, sBuf, version, bodyEnd,
                                            stringEnd, value);
    };
    const auto readShort = [version, buf, bodyEnd](std::uint16_t& value) {
        std::int32_t parsedValue = 0;
        if (!readBitShortWithinBody(buf, version, bodyEnd, parsedValue))
            return false;
        value = static_cast<std::uint16_t>(parsedValue);
        return true;
    };
    const auto readLong = [version, buf, bodyEnd](std::uint32_t& value) {
        std::int32_t parsedValue = 0;
        if (!readBitLongWithinBody(buf, version, bodyEnd, parsedValue))
            return false;
        value = static_cast<std::uint32_t>(parsedValue);
        return true;
    };
    const auto readSignedLong = [version, buf, bodyEnd](std::int32_t& value) {
        return readBitLongWithinBody(buf, version, bodyEnd, value);
    };
    const auto readDouble = [version, buf, bodyEnd](double& value) {
        return readBitDoubleWithinBody(buf, version, bodyEnd, value)
            && std::isfinite(value);
    };
    const auto readFlag = [version, buf, bodyEnd](bool& value) {
        return readBitWithinBody(buf, version, bodyEnd, value);
    };
    const auto readRaw = [version, buf, bodyEnd](std::uint8_t& value) {
        return readRawCharWithinBody(buf, version, bodyEnd, value);
    };
    const auto readColor = [version, buf, sBuf, bodyEnd, stringEnd](
                               int& value) {
        std::uint32_t parsedValue = 0;
        if (!readCmColorWithinBounds(buf, sBuf, version, bodyEnd, stringEnd,
                                     parsedValue))
            return false;
        value = static_cast<int>(parsedValue);
        return true;
    };
    const auto readHandle = [this, &hBuff, handleEndBit](std::uint32_t& value) {
        dwgHandle parsedHandle;
        if (!readBoundedObjectHandle(hBuff, handle, false, parsedHandle,
                                     handleEndBit))
            return false;
        value = parsedHandle.ref;
        return true;
    };

    if (!readShort(m_modelDoc.m_modelDocClassVersion)
        || !readText(m_modelDoc.m_description)
        || !readFlag(m_modelDoc.m_modifiedForRecompute))
        return fail();
    if (version >= DRW::AC1032) {
        if (!readText(m_modelDoc.m_displayName)
            || !readLong(m_modelDoc.m_viewStyleFlags))
            return fail();
    }

    if (!readShort(m_classVersion) || !readLong(m_flags)
        || !readHandle(m_identifierStyleHandle)
        || !readColor(m_identifierColor)
        || !readDouble(m_identifierHeight)
        || !readText(m_identifierExcludeCharacters)
        || !readDouble(m_identifierOffset)
        || !readRaw(m_identifierPlacement)
        || !readHandle(m_arrowSymbolHandle)
        || !readColor(m_arrowSymbolColor)
        || !readDouble(m_arrowSymbolSize)
        || !readHandle(m_boundaryLineTypeHandle)
        || !readSignedLong(m_boundaryLineWeight)
        || !readColor(m_boundaryLineColor)
        || !readHandle(m_viewLabelTextStyleHandle)
        || !readColor(m_viewLabelTextColor)
        || !readDouble(m_viewLabelTextHeight)
        || !readLong(m_viewLabelAttachment)
        || !readDouble(m_viewLabelOffset)
        || !readLong(m_viewLabelAlignment)
        || !readText(m_viewLabelPattern)
        || !readHandle(m_connectionLineTypeHandle)
        || !readSignedLong(m_connectionLineWeight)
        || !readColor(m_connectionLineColor)
        || !readHandle(m_borderLineTypeHandle)
        || !readSignedLong(m_borderLineWeight)
        || !readColor(m_borderLineColor)
        || !readRaw(m_modelEdge))
        return fail();
    if (!buf->isGood() || !sBuf->isGood() || !hBuff.isGood()
        || !bodyFits())
        return fail();
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return true;
    } catch (...) {
        return fail();
    }
}

void DRW_SectionViewStyle::reset() {
    tType = DRW::SECTIONVIEWSTYLE;
    m_modelDoc = DRW_ModelDocViewStyle();
    m_classVersion = 0;
    m_flags = 0;
    m_identifierStyleHandle = 0;
    m_identifierColor = 256;
    m_identifierHeight = 0.0;
    m_arrowStartSymbolHandle = 0;
    m_arrowEndSymbolHandle = 0;
    m_arrowSymbolColor = 256;
    m_arrowSymbolSize = 0.0;
    m_identifierExcludeCharacters.clear();
    m_identifierPosition = 0;
    m_identifierOffset = 0.0;
    m_arrowPosition = 0;
    m_arrowSymbolExtensionLength = 0.0;
    m_planeLineTypeHandle = 0;
    m_planeLineWeight = 0;
    m_planeLineColor = 256;
    m_bendLineTypeHandle = 0;
    m_bendLineWeight = 0;
    m_bendLineColor = 256;
    m_bendLineLength = 0.0;
    m_endLineOvershoot = 0.0;
    m_endLineLength = 0.0;
    m_viewLabelTextStyleHandle = 0;
    m_viewLabelTextColor = 256;
    m_viewLabelTextHeight = 0.0;
    m_viewLabelAttachment = 0;
    m_viewLabelOffset = 0.0;
    m_viewLabelAlignment = 0;
    m_viewLabelPattern.clear();
    m_hatchColor = 256;
    m_hatchBackgroundColor = 257;
    m_hatchPattern.clear();
    m_hatchScale = 1.0;
    m_hatchTransparency = 0;
    m_unknownB1 = false;
    m_unknownB2 = false;
    m_hatchAngles.clear();
    m_dxfSubclass.clear();
    m_dxfGroup = -1;
    m_dxfHandleCount = m_dxfColorCount = m_dxfDoubleCount = m_dxfLongCount = 0;
    m_dxfBoolCount = 0;
    m_dxfExpectedHatchAngles = 0;
    DRW_TableEntry::reset();
}

bool DRW_SectionViewStyle::parseCode(int code, const std::unique_ptr<dxfReader>& reader) {
    if (code == 100) {
        m_dxfSubclass = reader->getUtf8String();
        m_dxfGroup = -1;
        m_dxfHandleCount = m_dxfColorCount = m_dxfDoubleCount = m_dxfLongCount = 0;
        m_dxfBoolCount = 0;
        return true;
    }
    if (m_dxfSubclass == "AcDbModelDocViewStyle") {
        switch (code) {
        case 70: m_modelDoc.m_modelDocClassVersion = reader->getInt32(); return true;
        case 3:  m_modelDoc.m_description = reader->getUtf8String(); return true;
        case 290: m_modelDoc.m_modifiedForRecompute = reader->getBool(); return true;
        case 300: m_modelDoc.m_displayName = reader->getUtf8String(); return true;
        case 90: m_modelDoc.m_viewStyleFlags = static_cast<std::uint32_t>(reader->getInt32()); return true;
        default: return DRW_TableEntry::parseCode(code, reader);
        }
    }
    if (m_dxfSubclass != "AcDbSectionViewStyle")
        return DRW_TableEntry::parseCode(code, reader);

    if (code == 71) {
        m_dxfGroup = reader->getInt32();
        m_dxfHandleCount = m_dxfColorCount = m_dxfDoubleCount = m_dxfLongCount = 0;
        m_dxfBoolCount = 0;
        return true;
    }
    switch (code) {
    case 70:
        m_classVersion = reader->getInt32();
        return true;
    case 340: {
        const std::uint32_t ref = static_cast<std::uint32_t>(reader->getHandleString());
        if (m_dxfGroup == 1) {
            if (m_dxfHandleCount == 0) m_identifierStyleHandle = ref;
            else if (m_dxfHandleCount == 1) m_arrowStartSymbolHandle = ref;
            else m_arrowEndSymbolHandle = ref;
            ++m_dxfHandleCount;
        } else if (m_dxfGroup == 2) {
            if (m_dxfHandleCount++ == 0) m_planeLineTypeHandle = ref;
            else m_bendLineTypeHandle = ref;
        } else if (m_dxfGroup == 3) {
            m_viewLabelTextStyleHandle = ref;
        }
        return true;
    }
    case 62: {
        const int color = reader->getInt32();
        if (m_dxfGroup == 1) {
            if (m_dxfColorCount++ == 0) m_identifierColor = color;
            else m_arrowSymbolColor = color;
        } else if (m_dxfGroup == 2) {
            if (m_dxfColorCount++ == 0) m_planeLineColor = color;
            else m_bendLineColor = color;
        } else if (m_dxfGroup == 3) {
            m_viewLabelTextColor = color;
        } else if (m_dxfGroup == 4) {
            if (m_dxfColorCount++ == 0) m_hatchColor = color;
            else m_hatchBackgroundColor = color;
        }
        return true;
    }
    case 40: {
        const double value = reader->getDouble();
        if (m_dxfGroup == 1) {
            if (m_dxfDoubleCount == 0) m_identifierHeight = value;
            else if (m_dxfDoubleCount == 1) m_arrowSymbolSize = value;
            else if (m_dxfDoubleCount == 2) m_arrowSymbolExtensionLength = value;
            else m_identifierOffset = value;
            ++m_dxfDoubleCount;
        } else if (m_dxfGroup == 2) {
            if (m_dxfDoubleCount == 0) m_bendLineLength = value;
            else if (m_dxfDoubleCount == 1) m_endLineOvershoot = value;
            else m_endLineLength = value;
            ++m_dxfDoubleCount;
        } else if (m_dxfGroup == 3) {
            if (m_dxfDoubleCount++ == 0) m_viewLabelTextHeight = value;
            else m_viewLabelOffset = value;
        } else if (m_dxfGroup == 4) {
            if (m_dxfDoubleCount++ == 0) m_hatchScale = value;
            else m_hatchAngles.push_back(value);
        }
        return true;
    }
    case 90: {
        const std::int32_t value = reader->getInt32();
        if (m_dxfGroup == 0 || m_dxfGroup == -1) m_flags = static_cast<std::uint32_t>(value);
        else if (m_dxfGroup == 1) {
            if (m_dxfLongCount++ == 0) m_identifierPosition = value;
            else m_arrowPosition = value;
        } else if (m_dxfGroup == 2) {
            if (m_dxfLongCount++ == 0) m_planeLineWeight = value;
            else m_bendLineWeight = value;
        } else if (m_dxfGroup == 3) {
            if (m_dxfLongCount++ == 0) m_viewLabelAttachment = static_cast<std::uint32_t>(value);
            else m_viewLabelAlignment = static_cast<std::uint32_t>(value);
        } else if (m_dxfGroup == 4) {
            if (m_dxfLongCount++ == 0) m_hatchTransparency = value;
            else m_dxfExpectedHatchAngles = static_cast<std::uint32_t>(value);
        }
        return true;
    }
    case 290:
        if (m_dxfGroup == 4) {
            if (m_dxfBoolCount++ == 0) m_unknownB1 = reader->getBool();
            else m_unknownB2 = reader->getBool();
        } else {
            reader->getBool();
        }
        return true;
    case 300:
        if (m_dxfGroup == 1) m_identifierExcludeCharacters = reader->getUtf8String();
        else if (m_dxfGroup == 3) m_viewLabelPattern = reader->getUtf8String();
        else if (m_dxfGroup == 4) m_hatchPattern = reader->getUtf8String();
        else reader->getUtf8String();
        return true;
    default:
        return DRW_TableEntry::parseCode(code, reader);
    }
}

bool DRW_SectionViewStyle::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs) {
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr) {
        reset();
        return false;
    }
    try {
    reset();
    dwgBuffer sBuff = *buf;
    dwgBuffer *sBuf = version > DRW::AC1018 ? &sBuff : buf;
    bool ret = DRW_TableEntry::parseDwg(version, buf, sBuf, bs);
    DRW_DBG("\n***************************** parsing SECTIONVIEWSTYLE *****************\n");
    if (!ret) return fail();

    std::uint32_t bodyEnd = objSize;
    std::uint32_t stringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!sBuf->getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(sBuf) != stringStartBit)
            return fail();
        bodyEnd = static_cast<std::uint32_t>(stringStartBit);
        stringEnd = static_cast<std::uint32_t>(stringEndBit);
    }
    const auto bodyFits = [buf, sBuf, bodyEnd, stringEnd]() {
        return objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd)
            && objectBodyFitsSize(currentObjectDwgBit(sBuf), stringEnd);
    };
    if (!bodyFits())
        return fail();

    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();

    const auto readText = [version, buf, sBuf, bodyEnd, stringEnd](
                              UTF8STRING& value) {
        return readVariableTextWithinBounds(buf, sBuf, version, bodyEnd,
                                            stringEnd, value);
    };
    const auto readShort = [version, buf, bodyEnd](std::uint16_t& value) {
        std::int32_t parsedValue = 0;
        if (!readBitShortWithinBody(buf, version, bodyEnd, parsedValue))
            return false;
        value = static_cast<std::uint16_t>(parsedValue);
        return true;
    };
    const auto readLong = [version, buf, bodyEnd](std::uint32_t& value) {
        std::int32_t parsedValue = 0;
        if (!readBitLongWithinBody(buf, version, bodyEnd, parsedValue))
            return false;
        value = static_cast<std::uint32_t>(parsedValue);
        return true;
    };
    const auto readSignedLong = [version, buf, bodyEnd](std::int32_t& value) {
        return readBitLongWithinBody(buf, version, bodyEnd, value);
    };
    const auto readDouble = [version, buf, bodyEnd](double& value) {
        return readBitDoubleWithinBody(buf, version, bodyEnd, value)
            && std::isfinite(value);
    };
    const auto readFlag = [version, buf, bodyEnd](bool& value) {
        return readBitWithinBody(buf, version, bodyEnd, value);
    };
    const auto readColor = [version, buf, sBuf, bodyEnd, stringEnd](
                               int& value) {
        std::uint32_t parsedValue = 0;
        if (!readCmColorWithinBounds(buf, sBuf, version, bodyEnd, stringEnd,
                                     parsedValue))
            return false;
        value = static_cast<int>(parsedValue);
        return true;
    };
    const auto readHandle = [this, &hBuff, handleEndBit](std::uint32_t& value) {
        dwgHandle parsedHandle;
        if (!readBoundedObjectHandle(hBuff, handle, false, parsedHandle,
                                     handleEndBit))
            return false;
        value = parsedHandle.ref;
        return true;
    };

    if (!readShort(m_modelDoc.m_modelDocClassVersion)
        || !readText(m_modelDoc.m_description)
        || !readFlag(m_modelDoc.m_modifiedForRecompute))
        return fail();
    if (version >= DRW::AC1032) {
        if (!readText(m_modelDoc.m_displayName)
            || !readLong(m_modelDoc.m_viewStyleFlags))
            return fail();
    }

    if (!readShort(m_classVersion)
        || !readLong(m_flags)
        || !readHandle(m_identifierStyleHandle)
        || !readColor(m_identifierColor)
        || !readDouble(m_identifierHeight)
        || !readHandle(m_arrowStartSymbolHandle)
        || !readHandle(m_arrowEndSymbolHandle)
        || !readColor(m_arrowSymbolColor)
        || !readDouble(m_arrowSymbolSize)
        || !readText(m_identifierExcludeCharacters)
        || !readDouble(m_arrowSymbolExtensionLength)
        || !readHandle(m_planeLineTypeHandle)
        || !readSignedLong(m_planeLineWeight)
        || !readColor(m_planeLineColor)
        || !readHandle(m_bendLineTypeHandle)
        || !readSignedLong(m_bendLineWeight)
        || !readColor(m_bendLineColor)
        || !readDouble(m_bendLineLength)
        || !readDouble(m_endLineLength)
        || !readHandle(m_viewLabelTextStyleHandle)
        || !readColor(m_viewLabelTextColor)
        || !readDouble(m_viewLabelTextHeight)
        || !readLong(m_viewLabelAttachment)
        || !readDouble(m_viewLabelOffset)
        || !readLong(m_viewLabelAlignment)
        || !readText(m_viewLabelPattern)
        || !readColor(m_hatchColor)
        || !readColor(m_hatchBackgroundColor)
        || !readText(m_hatchPattern)
        || !readDouble(m_hatchScale)
        || !readSignedLong(m_hatchTransparency)
        || !readFlag(m_unknownB1)
        || !readFlag(m_unknownB2)
        || !readSignedLong(m_identifierPosition)
        || !readDouble(m_identifierOffset)
        || !readSignedLong(m_arrowPosition)
        || !readDouble(m_endLineOvershoot))
        return fail();

    std::int32_t hatchAngleCount = 0;
    if (!readSignedLong(hatchAngleCount))
        return fail();
    if (hatchAngleCount < 0 || hatchAngleCount > 100000)
        return fail();
    if (!countFitsObjectBody(buf, version, bodyEnd, hatchAngleCount, 2))
        return fail();
    m_hatchAngles.clear();
    if (!DRW::reserve(m_hatchAngles, hatchAngleCount))
        return fail();
    for (std::int32_t i = 0; i < hatchAngleCount; ++i) {
        double hatchAngle = 0.0;
        if (!readDouble(hatchAngle))
            return fail();
        m_hatchAngles.push_back(hatchAngle);
    }

    if (!buf->isGood() || !sBuf->isGood() || !hBuff.isGood()
        || !bodyFits())
        return fail();
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return true;
    } catch (...) {
        return fail();
    }
}

void DRW_BreakData::reset() {
    tType = DRW::BREAKDATA;
    m_pointRefHandles.clear();
    m_dimensionHandle = 0;
    m_dxfInBreakData = false;
    DRW_TableEntry::reset();
}

bool DRW_BreakData::parseCode(int code, const std::unique_ptr<dxfReader>& reader) {
    if (code == 100) {
        m_dxfInBreakData = reader->getUtf8String() == "AcDbBreakData";
        return true;
    }
    if (!m_dxfInBreakData)
        return DRW_TableEntry::parseCode(code, reader);
    switch (code) {
    case 90:
        reader->getInt32();
        return true;
    case 330:
        if (m_pointRefHandles.size() >= dwgSafety::MaxOwnedObjectCount)
            return false;
        m_pointRefHandles.push_back(static_cast<std::uint32_t>(reader->getHandleString()));
        return true;
    case 331:
        m_dimensionHandle = static_cast<std::uint32_t>(reader->getHandleString());
        return true;
    default:
        return DRW_TableEntry::parseCode(code, reader);
    }
}

bool DRW_BreakData::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs) {
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr) {
        reset();
        return false;
    }
    try {
    reset();
    dwgBuffer stringBuffer = *buf;
    dwgBuffer *stringBuf = version > DRW::AC1018 ? &stringBuffer : nullptr;
    bool ret = DRW_TableEntry::parseDwg(version, buf, stringBuf, bs);
    DRW_DBG("\n***************************** parsing BREAKDATA ************************\n");
    if (!ret) return fail();
    std::uint32_t bodyEnd = objSize;
    if (version > DRW::AC1018
        && !objectBodyDataEnd(version, stringBuf, objSize, bodyEnd))
        return fail();
    if (!objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd)
        || !dictionaryBitRangeAvailable(buf, version, bodyEnd, 2))
        return fail();

    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();

    std::int32_t pointRefCount = 0;
    if (!readBitLongWithinBody(buf, version, bodyEnd, pointRefCount)
        || pointRefCount < 0 || pointRefCount > 100000)
        return fail();
    if (!objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd))
        return fail();
    const std::uint64_t requiredHandles =
        static_cast<std::uint64_t>(pointRefCount) + 1u;
    std::uint64_t currentHandleBit = 0;
    if (!objectCurrentBit(hBuff, currentHandleBit)
        || currentHandleBit > handleEndBit
        || requiredHandles > (handleEndBit - currentHandleBit) / 8u)
        return fail();

    dwgBuffer handleProbe = hBuff;
    std::vector<std::uint32_t> pointRefs;
    if (!DRW::reserve(pointRefs, pointRefCount))
        return fail();
    for (std::int32_t i = 0; i < pointRefCount; ++i) {
        std::uint32_t pointRef = 0;
        if (!readObjectHandleRefTransactional(&handleProbe, pointRef,
                                              handleEndBit))
            return fail();
        pointRefs.push_back(pointRef);
    }
    std::uint32_t dimensionHandle = 0;
    if (!readObjectHandleRefTransactional(&handleProbe, dimensionHandle,
                                          handleEndBit))
        return fail();
    if (!buf->isGood() || !handleProbe.isGood()
        || !objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd))
        return fail();
    m_pointRefHandles = std::move(pointRefs);
    m_dimensionHandle = dimensionHandle;
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return true;
    } catch (...) {
        return fail();
    }
}

bool DRW_BreakPointRef::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs) {
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr) {
        reset();
        return false;
    }
    try {
    reset();
    dwgBuffer stringBuffer = *buf;
    dwgBuffer *stringBuf = version > DRW::AC1018 ? &stringBuffer : nullptr;
    bool ret = DRW_TableEntry::parseDwg(version, buf, stringBuf, bs);
    DRW_DBG("\n***************************** parsing BREAKPOINTREF ********************\n");
    if (!ret) return fail();
    std::uint32_t bodyEnd = objSize;
    if (version > DRW::AC1018
        && !objectBodyDataEnd(version, stringBuf, objSize, bodyEnd))
        return fail();
    if (!objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd))
        return fail();
    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();
    if (!buf->isGood() || !hBuff.isGood()
        || !objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd))
        return fail();
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return true;
    } catch (...) {
        return fail();
    }
}

bool DRW_VisualStyle::parseCode(int code, const std::unique_ptr<dxfReader>& reader){
    // AcDbVisualStyle DXF: description (2 / 4) + style type (70).  Matches
    // dwgTs's VISUALSTYLE decode; the per-property render settings (face/edge/
    // display) stay round-tripped raw only on the DXF path.
    switch (code) {
    case 2:
    case 4:
        desc = reader->getUtf8String();
        break;
    case 70:
        type = reader->getInt32();
        break;
    default:
        return DRW_TableEntry::parseCode(code, reader);
    }
    return true;
}

// object is parsed from a size-bounded buffer so any unread tail is
// safely discarded by the caller.
//
// Full AcDbVisualStyle body decode. Field order transcribed 1:1 from dwgTs
// parseObjects.ts parseVisualStyle / readVisualStyleLegacyBody (1587-1627) /
// readVisualStyleR2010bBody (1762-1832) / readVisualStyleR2013bExpansion
// (1651-1710), cross-checked against libreDWG dwg2.spec:2119-2289.
// Bit-primitive map: readBitLong->getBitLong, readBitDouble->getBitDouble,
// readBitShort->getBitShort, readBit->getBit, readRawChar->getRawChar8,
// readCmColor->readObjectCmColor, readObjectText->getVariableText.
bool DRW_VisualStyle::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs){
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr)
        return fail();
    try {
    reset();
    dwgBuffer sBuff = *buf;
    dwgBuffer *sBuf = buf;
    if (version > DRW::AC1018) {  // 2007+ uses separate string stream
        sBuf = &sBuff;
    }
    bool ret = DRW_TableEntry::parseDwg(version, buf, sBuf, bs);
    DRW_DBG("\n***************************** parsing VISUALSTYLE *********************\n");
    if (!ret) return fail();

    // The body cursor and the R2007+ string cursor are advanced on private
    // forks. Every primitive must fit before it commits, so a truncated body
    // cannot consume the following handle stream or publish partial state.
    dwgBuffer bodyBuff = *buf;
    dwgBuffer stringBuff = sBuff;
    dwgBuffer *bodyBuf = &bodyBuff;
    dwgBuffer *bodySBuf = version > DRW::AC1018 ? &stringBuff : bodyBuf;
    std::uint32_t bodyEnd = objSize;
    std::uint32_t stringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!sBuff.getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(&sBuff) != stringStartBit)
            return fail();
        bodyEnd = static_cast<std::uint32_t>(stringStartBit);
        stringEnd = static_cast<std::uint32_t>(stringEndBit);
    }
    const auto bodyBytesRemaining = [&]() {
        if (version >= DRW::AC1015 && bodyEnd != 0)
            return currentObjectDwgBit(bodyBuf) < bodyEnd;
        return bodyBuf->numRemainingBytes() > 0;
    };
    const auto readLong = [&](std::int32_t& value) {
        return readBitLongWithinBody(bodyBuf, version, bodyEnd, value);
    };
    const auto readShort = [&](std::int32_t& value) {
        return readBitShortWithinBody(bodyBuf, version, bodyEnd, value);
    };
    const auto readDouble = [&](double& value) {
        return readBitDoubleWithinBody(bodyBuf, version, bodyEnd, value)
            && std::isfinite(value);
    };
    const auto readBit = [&](bool& value) {
        return readBitWithinBody(bodyBuf, version, bodyEnd, value);
    };
    const auto readByte = [&](std::int32_t& value) {
        std::uint8_t parsed = 0;
        if (!readRawCharWithinBody(bodyBuf, version, bodyEnd, parsed))
            return false;
        value = parsed;
        return true;
    };
    const auto readColor = [&](int& value) {
        std::uint32_t parsed = 0;
        if (!readCmColorWithinBounds(bodyBuf, bodySBuf, version, bodyEnd,
                                     stringEnd, parsed))
            return false;
        value = static_cast<int>(parsed);
        return true;
    };
    const auto readText = [&](UTF8STRING& value) {
        return readVariableTextWithinBounds(bodyBuf, bodySBuf, version,
                                            bodyEnd, stringEnd, value);
    };
    const auto readCompanion = [&]() {
        std::int32_t ignored = 0;
        return readShort(ignored);
    };

    if (bodyBytesRemaining() && !readText(desc))
        return fail();
    if (bodyBytesRemaining() && !readLong(type))
        return fail();

    if (version < DRW::AC1024 && bodyBytesRemaining()) {
        if (!readLong(m_body.faceLightingModel)
            || !readLong(m_body.faceLightingQuality)
            || !readLong(m_body.faceColorMode)
            || !readDouble(m_body.faceOpacity)
            || !readDouble(m_body.faceSpecular)
            || !readColor(m_body.faceMonoColor)
            || !readLong(m_body.faceModifier)
            || !readLong(m_body.edgeModel)
            || !readLong(m_body.edgeStyle)
            || !readColor(m_body.edgeIntersectionColor)
            || !readColor(m_body.edgeObscuredColor)
            || !readLong(m_body.edgeObscuredLtype)
            || !readDouble(m_body.edgeCreaseAngle)
            || !readLong(m_body.edgeModifier)
            || !readColor(m_body.edgeColor)
            || !readDouble(m_body.edgeOpacity)
            || !readShort(m_body.edgeWidth)
            || !readShort(m_body.edgeOverhang)
            || !readLong(m_body.edgeJitter)
            || !readColor(m_body.edgeSilhouetteColor)
            || !readShort(m_body.edgeSilhouetteWidth)
            || !readByte(m_body.edgeHaloGap)
            || !readShort(m_body.edgeIsolines)
            || !readBit(m_body.edgeDoHidePrecision)
            || !readShort(m_body.edgeStyleApply)
            || !readShort(m_body.edgeIntersectionLtype)
            || !readLong(m_body.displaySettings))
            return fail();
        std::int32_t brightness = 0;
        if (!readLong(brightness))
            return fail();
        m_body.displayBrightness = static_cast<double>(brightness);

        if (bodyBytesRemaining()) {
            double ignoredReserved = 0.0;
            if (!readLong(m_body.displayShadowType)
                || (version >= DRW::AC1021 && !readDouble(ignoredReserved))
                || !readBit(m_body.internalOnly))
                return fail();
        }
    } else if (version >= DRW::AC1024 && bodyBytesRemaining()) {
        if (!readShort(m_body.extLightingModel)
            || !readBit(m_body.internalOnly)
            || !readLong(m_body.faceLightingModel) || !readCompanion()
            || !readLong(m_body.faceLightingQuality) || !readCompanion()
            || !readLong(m_body.faceColorMode) || !readCompanion()
            || !readShort(m_body.faceModifier) || !readCompanion()
            || !readDouble(m_body.faceOpacity) || !readCompanion()
            || !readDouble(m_body.faceSpecular) || !readCompanion()
            || !readColor(m_body.faceMonoColor) || !readCompanion()
            || !readLong(m_body.edgeModel) || !readCompanion()
            || !readLong(m_body.edgeStyle) || !readCompanion()
            || !readColor(m_body.edgeIntersectionColor) || !readCompanion()
            || !readColor(m_body.edgeObscuredColor) || !readCompanion()
            || !readLong(m_body.edgeObscuredLtype) || !readCompanion()
            || !readLong(m_body.edgeIntersectionLtype) || !readCompanion()
            || !readDouble(m_body.edgeCreaseAngle) || !readCompanion()
            || !readLong(m_body.edgeModifier) || !readCompanion()
            || !readColor(m_body.edgeColor) || !readCompanion()
            || !readDouble(m_body.edgeOpacity) || !readCompanion()
            || !readLong(m_body.edgeWidth) || !readCompanion()
            || !readLong(m_body.edgeOverhang) || !readCompanion()
            || !readLong(m_body.edgeJitter) || !readCompanion()
            || !readColor(m_body.edgeSilhouetteColor) || !readCompanion()
            || !readLong(m_body.edgeSilhouetteWidth) || !readCompanion()
            || !readLong(m_body.edgeHaloGap) || !readCompanion())
            return fail();
        std::int32_t isolines = 0;
        if (!readLong(isolines) || !readCompanion())
            return fail();
        m_body.edgeIsolines = isolines > DRW_VisualStyleBody::kMaxEdgeIsolines
            ? DRW_VisualStyleBody::kMaxEdgeIsolines : isolines;
        if (!readBit(m_body.edgeDoHidePrecision) || !readCompanion()
            || !readLong(m_body.displaySettings) || !readCompanion()
            || !readDouble(m_body.displayBrightness) || !readCompanion()
            || !readLong(m_body.displayShadowType) || !readCompanion())
            return fail();

        if (version >= DRW::AC1027) {
            m_body.hasR2013bExpansion = true;
            if (!readBit(m_body.bProp1c) || !readCompanion()
                || !readBit(m_body.bProp1d) || !readCompanion()
                || !readBit(m_body.bProp1e) || !readCompanion()
                || !readBit(m_body.bProp1f) || !readCompanion()
                || !readBit(m_body.bProp20) || !readCompanion()
                || !readBit(m_body.bProp21) || !readCompanion()
                || !readBit(m_body.bProp22) || !readCompanion()
                || !readBit(m_body.bProp23) || !readCompanion()
                || !readBit(m_body.bProp24) || !readCompanion()
                || !readLong(m_body.blProp25) || !readCompanion()
                || !readDouble(m_body.bdProp26) || !readCompanion()
                || !readDouble(m_body.bdProp27) || !readCompanion()
                || !readLong(m_body.blProp28) || !readCompanion()
                || !readColor(m_body.cProp29) || !readCompanion()
                || !readLong(m_body.blProp2a) || !readCompanion()
                || !readLong(m_body.blProp2b) || !readCompanion()
                || !readColor(m_body.cProp2c) || !readCompanion()
                || !readBit(m_body.bProp2d) || !readCompanion()
                || !readLong(m_body.blProp2e) || !readCompanion()
                || !readLong(m_body.blProp2f) || !readCompanion()
                || !readLong(m_body.blProp30) || !readCompanion()
                || !readBit(m_body.bProp31) || !readCompanion()
                || !readLong(m_body.blProp32) || !readCompanion()
                || !readColor(m_body.cProp33) || !readCompanion()
                || !readDouble(m_body.bdProp34) || !readCompanion()
                || !readLong(m_body.edgeWiggle) || !readCompanion()
                || !readText(m_body.strokes) || !readCompanion()
                || !readBit(m_body.bProp37) || !readCompanion()
                || !readDouble(m_body.bdProp38) || !readCompanion()
                || !readDouble(m_body.bdProp39) || !readCompanion())
                return fail();
        }
    }

    *buf = bodyBuff;
    if (version > DRW::AC1018)
        sBuff = stringBuff;

    // The common handle stream is detached from the data body in every
    // version carrying an object-size boundary. Validate it from a fork so
    // the body cursor remains available to the raw replay path.
    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();

    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;

    // m_bodyDecoded is true only when both the detached string/data streams
    // and the common handle stream were consumed without a structural error.
    m_bodyDecoded = buf->isGood() && sBuf->isGood() && hBuff.isGood()
        && objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd)
        && objectBodyFitsSize(currentObjectDwgBit(sBuf), stringEnd);
    return m_bodyDecoded ? true : fail();
    } catch (...) {
        return fail();
    }
}

bool DRW_VisualStyle::encodeDwg(DRW::Version version, dwgBufferW *buf,
                                dwgBufferW *strBuf,
                                dwgBufferW *handleBuf) const {
    if (buf == nullptr || version < DRW::AC1015
        || reactorHandles.size() > dwgSafety::MaxReactorCount
        || extensionDictionaryFlag() > 1)
        return false;
    const auto validColor = [](int color) {
        return validUnsignedBitShort(color);
    };
    const auto validDouble = [](double value) {
        return std::isfinite(value);
    };
    if (!validColor(m_body.faceMonoColor)
        || !validColor(m_body.edgeIntersectionColor)
        || !validColor(m_body.edgeObscuredColor)
        || !validColor(m_body.edgeColor)
        || !validColor(m_body.edgeSilhouetteColor)
        || !validDouble(m_body.faceOpacity)
        || !validDouble(m_body.faceSpecular)
        || !validDouble(m_body.edgeCreaseAngle)
        || !validDouble(m_body.edgeOpacity)
        || !validDouble(m_body.displayBrightness)
        || m_body.edgeIsolines < 0
        || m_body.edgeIsolines > DRW_VisualStyleBody::kMaxEdgeIsolines
        || (version < DRW::AC1024
            && (!validUnsignedBitShort(m_body.edgeWidth)
                || !validUnsignedBitShort(m_body.edgeOverhang)
                || !validUnsignedBitShort(m_body.edgeSilhouetteWidth)
                || !validUnsignedBitShort(m_body.edgeStyleApply)
                || !validUnsignedBitShort(m_body.edgeIntersectionLtype)
                || m_body.edgeHaloGap < 0
                || m_body.edgeHaloGap
                    > std::numeric_limits<std::uint8_t>::max()))
        || (version >= DRW::AC1024
            && !validUnsignedBitShort(m_body.extLightingModel))
        || (version >= DRW::AC1027
            && (!validDouble(m_body.bdProp26)
                || !validDouble(m_body.bdProp27)
                || !validDouble(m_body.bdProp34)
                || !validDouble(m_body.bdProp38)
                || !validDouble(m_body.bdProp39)
                || !validColor(m_body.cProp29)
                || !validColor(m_body.cProp2c)
                || !validColor(m_body.cProp33)))
        )
        return false;

    dwgBufferW *sb = strBuf != nullptr && version > DRW::AC1018
        ? strBuf : buf;
    dwgBufferW *hb = handleBuf != nullptr && version > DRW::AC1014
        ? handleBuf : buf;
    const auto putColor = [version](dwgBufferW *target, int color) {
        target->putCmColor(version, static_cast<std::uint16_t>(color));
    };
    const auto putShort = [](dwgBufferW *target, int value) {
        target->putBitShort(static_cast<std::uint16_t>(value));
    };
    const auto putByte = [](dwgBufferW *target, int value) {
        target->putRawChar8(static_cast<std::uint8_t>(value));
    };
    const auto putIsolines = [](dwgBufferW *target, int value) {
        target->putBitLong(value);
    };

    sb->putVariableText(version, desc);
    buf->putBitLong(type);

    if (version < DRW::AC1024) {
        buf->putBitLong(m_body.faceLightingModel);
        buf->putBitLong(m_body.faceLightingQuality);
        buf->putBitLong(m_body.faceColorMode);
        buf->putBitDouble(m_body.faceOpacity);
        buf->putBitDouble(m_body.faceSpecular);
        putColor(buf, m_body.faceMonoColor);
        buf->putBitLong(m_body.faceModifier);

        buf->putBitLong(m_body.edgeModel);
        buf->putBitLong(m_body.edgeStyle);
        putColor(buf, m_body.edgeIntersectionColor);
        putColor(buf, m_body.edgeObscuredColor);
        buf->putBitLong(m_body.edgeObscuredLtype);
        buf->putBitDouble(m_body.edgeCreaseAngle);
        buf->putBitLong(m_body.edgeModifier);
        putColor(buf, m_body.edgeColor);
        buf->putBitDouble(m_body.edgeOpacity);
        putShort(buf, m_body.edgeWidth);
        putShort(buf, m_body.edgeOverhang);
        buf->putBitLong(m_body.edgeJitter);
        putColor(buf, m_body.edgeSilhouetteColor);
        putShort(buf, m_body.edgeSilhouetteWidth);
        putByte(buf, m_body.edgeHaloGap);
        putShort(buf, m_body.edgeIsolines);
        buf->putBit(m_body.edgeDoHidePrecision ? 1 : 0);
        putShort(buf, m_body.edgeStyleApply);
        putShort(buf, m_body.edgeIntersectionLtype);

        buf->putBitLong(m_body.displaySettings);
        buf->putBitLong(visualStyleLong(m_body.displayBrightness));
        buf->putBitLong(m_body.displayShadowType);
        if (version >= DRW::AC1021)
            buf->putBitDouble(0.0); // bd2007_45, reserved by the layout
        buf->putBit(m_body.internalOnly ? 1 : 0);
    } else {
        putShort(buf, m_body.extLightingModel);
        buf->putBit(m_body.internalOnly ? 1 : 0);

        buf->putBitLong(m_body.faceLightingModel); putShort(buf, 0);
        buf->putBitLong(m_body.faceLightingQuality); putShort(buf, 0);
        buf->putBitLong(m_body.faceColorMode); putShort(buf, 0);
        putShort(buf, m_body.faceModifier); putShort(buf, 0);
        buf->putBitDouble(m_body.faceOpacity); putShort(buf, 0);
        buf->putBitDouble(m_body.faceSpecular); putShort(buf, 0);
        putColor(buf, m_body.faceMonoColor); putShort(buf, 0);

        buf->putBitLong(m_body.edgeModel); putShort(buf, 0);
        buf->putBitLong(m_body.edgeStyle); putShort(buf, 0);
        putColor(buf, m_body.edgeIntersectionColor); putShort(buf, 0);
        putColor(buf, m_body.edgeObscuredColor); putShort(buf, 0);
        buf->putBitLong(m_body.edgeObscuredLtype); putShort(buf, 0);
        buf->putBitLong(m_body.edgeIntersectionLtype); putShort(buf, 0);
        buf->putBitDouble(m_body.edgeCreaseAngle); putShort(buf, 0);
        buf->putBitLong(m_body.edgeModifier); putShort(buf, 0);
        putColor(buf, m_body.edgeColor); putShort(buf, 0);
        buf->putBitDouble(m_body.edgeOpacity); putShort(buf, 0);
        buf->putBitLong(m_body.edgeWidth); putShort(buf, 0);
        buf->putBitLong(m_body.edgeOverhang); putShort(buf, 0);
        buf->putBitLong(m_body.edgeJitter); putShort(buf, 0);
        putColor(buf, m_body.edgeSilhouetteColor); putShort(buf, 0);
        buf->putBitLong(m_body.edgeSilhouetteWidth); putShort(buf, 0);
        buf->putBitLong(m_body.edgeHaloGap); putShort(buf, 0);
        putIsolines(buf, m_body.edgeIsolines); putShort(buf, 0);
        buf->putBit(m_body.edgeDoHidePrecision ? 1 : 0); putShort(buf, 0);

        buf->putBitLong(m_body.displaySettings); putShort(buf, 0);
        buf->putBitDouble(m_body.displayBrightness); putShort(buf, 0);
        buf->putBitLong(m_body.displayShadowType); putShort(buf, 0);

        if (version >= DRW::AC1027) {
            buf->putBit(m_body.bProp1c ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp1d ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp1e ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp1f ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp20 ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp21 ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp22 ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp23 ? 1 : 0); putShort(buf, 0);
            buf->putBit(m_body.bProp24 ? 1 : 0); putShort(buf, 0);
            buf->putBitLong(m_body.blProp25); putShort(buf, 0);
            buf->putBitDouble(m_body.bdProp26); putShort(buf, 0);
            buf->putBitDouble(m_body.bdProp27); putShort(buf, 0);
            buf->putBitLong(m_body.blProp28); putShort(buf, 0);
            putColor(buf, m_body.cProp29); putShort(buf, 0);
            buf->putBitLong(m_body.blProp2a); putShort(buf, 0);
            buf->putBitLong(m_body.blProp2b); putShort(buf, 0);
            putColor(buf, m_body.cProp2c); putShort(buf, 0);
            buf->putBit(m_body.bProp2d ? 1 : 0); putShort(buf, 0);
            buf->putBitLong(m_body.blProp2e); putShort(buf, 0);
            buf->putBitLong(m_body.blProp2f); putShort(buf, 0);
            buf->putBitLong(m_body.blProp30); putShort(buf, 0);
            buf->putBit(m_body.bProp31 ? 1 : 0); putShort(buf, 0);
            buf->putBitLong(m_body.blProp32); putShort(buf, 0);
            putColor(buf, m_body.cProp33); putShort(buf, 0);
            buf->putBitDouble(m_body.bdProp34); putShort(buf, 0);
            buf->putBitLong(m_body.edgeWiggle); putShort(buf, 0);
            sb->putVariableText(version, m_body.strokes); putShort(buf, 0);
            buf->putBit(m_body.bProp37 ? 1 : 0); putShort(buf, 0);
            buf->putBitDouble(m_body.bdProp38); putShort(buf, 0);
            buf->putBitDouble(m_body.bdProp39); putShort(buf, 0);
        }
    }

    putCommonObjectHandlePrefix(
        hb, static_cast<std::uint32_t>(parentHandle), reactorCount(),
        extensionDictionaryFlag(), &reactorHandles, xDictHandle);
    return buf->isGood() && sb->isGood() && hb->isGood();
}

// DBCOLOR (AcDbColor) per ODA spec §20.4 / libreDWG dwg2.spec:2404-2408.
// Layout: common preamble + FIELD_CMC + START_OBJECT_HANDLE_STREAM.
bool DRW_DbColor::parseDwg(DRW::Version version, dwgBuffer *buf, std::uint32_t bs){
    const auto fail = [this, buf]() {
        if (buf != nullptr)
            buf->invalidate();
        reset();
        return false;
    };
    if (buf == nullptr)
        return fail();
    try {
    reset();
    dwgBuffer sBuff = *buf;
    dwgBuffer *sBuf = buf;
    if (version > DRW::AC1018) {  // 2007+ uses separate string stream
        sBuf = &sBuff;
    }
    bool ret = DRW_TableEntry::parseDwg(version, buf, sBuf, bs);
    DRW_DBG("\n***************************** parsing DBCOLOR (AcDbColor) ***************\n");
    if (!ret)
        return fail();

    std::uint32_t bodyEnd = objSize;
    std::uint32_t stringEnd = objSize;
    if (version > DRW::AC1018 && objSize != 0) {
        std::uint64_t stringStartBit = 0;
        std::uint64_t stringEndBit = 0;
        if (!sBuff.getR2007StringStreamBounds(
                objSize, stringStartBit, stringEndBit)
            || stringStartBit > objSize || stringEndBit > objSize
            || stringEndBit < stringStartBit
            || stringStartBit > std::numeric_limits<std::uint32_t>::max()
            || stringEndBit > std::numeric_limits<std::uint32_t>::max()
            || currentObjectDwgBit(&sBuff) != stringStartBit)
            return fail();
        bodyEnd = static_cast<std::uint32_t>(stringStartBit);
        stringEnd = static_cast<std::uint32_t>(stringEndBit);
    }

    // Single FIELD_CMC per the spec. Stage the complete payload so a short
    // RGB/method/name field cannot advance the body or string cursor.
    std::int32_t rgb24 = -1;
    UTF8STRING cmcName, cmcBookName;
    std::uint32_t colorRet = 0;
    if (!readCmColorWithinBounds(buf, sBuf, version, bodyEnd, stringEnd,
                                 colorRet, &rgb24, &cmcName, &cmcBookName))
        return fail();
    if (!buf->isGood() || !sBuf->isGood())
        return fail();
    const std::uint16_t parsedColorIndex = static_cast<std::uint16_t>(colorRet);
    const std::int32_t parsedRgb = rgb24;
    const std::uint8_t parsedColorMethod =
        rgb24 != -1 ? 0xC2
        : colorRet == 0 ? 0xC1
        : colorRet == 256 ? 0xC0
        : 0xC3;
    const UTF8STRING parsedName = std::move(cmcName);
    const UTF8STRING parsedBookName = std::move(cmcBookName);
    // colorMethod isn't directly returned by getCmColor; deduce from rgb24
    // presence (true RGB) or fall back to ByLayer/ByBlock per colorRet.
    DRW_DBG("DBCOLOR method: "); DRW_DBGH(parsedColorMethod);
    DRW_DBG(" idx: "); DRW_DBG(parsedColorIndex);
    DRW_DBG(" rgb: "); DRW_DBGH(parsedRgb); DRW_DBG("\n");
    // START_OBJECT_HANDLE_STREAM follows the CMC. Fixed DBCOLOR records use
    // the object-size boundary in R2004+; raw pre-R2004 carriers keep handles
    // inline in the body. Restore the fork cursor because dwgBuffer copies
    // start at byte zero while preserving only the bit offset.
    dwgBuffer hBuff = *buf;
    std::uint64_t handleEndBit = 0;
    if (!objectHandleStreamEndBit(*buf, version, objSize, bs, handleEndBit))
        return fail();
    const std::uint64_t cursor = buf->getPosition();
    const std::uint8_t cursorBit = buf->getBitPos();
    if (!hBuff.setPosition(cursor))
        return fail();
    hBuff.setBitPos(cursorBit);
    seekObjectHandleStream(version, &hBuff, objSize,
                           /*includeLegacyObjectSize=*/true);
    std::uint32_t parsedParentHandle = 0;
    std::vector<std::uint32_t> parsedReactors;
    std::uint32_t parsedXDictHandle = 0;
    if (!hBuff.isGood()
        || !readObjectCommonHandles(&hBuff, handle, numReactors, xDictFlag,
                                    &parsedParentHandle, &parsedReactors,
                                    &parsedXDictHandle, handleEndBit))
        return fail();
    if (!buf->isGood() || !sBuf->isGood() || !hBuff.isGood()
        || !objectBodyFitsSize(currentObjectDwgBit(buf), bodyEnd)
        || !objectBodyFitsSize(currentObjectDwgBit(sBuf), stringEnd))
        return fail();

    colorIndex = parsedColorIndex;
    rgb = parsedRgb;
    colorMethod = parsedColorMethod;
    name = parsedName;
    bookName = parsedBookName;
    parentHandle = parsedParentHandle;
    reactorHandles = std::move(parsedReactors);
    xDictHandle = parsedXDictHandle;
    return true;
    } catch (...) {
        return fail();
    }
}

bool DRW_DbColor::encodeDwg(DRW::Version version, dwgBufferW *buf,
                            dwgBufferW *strBuf,
                            dwgBufferW *handleBuf) const {
    if (buf == nullptr || version < DRW::AC1018
        || !dwgSafety::validReactorCount(numReactors)
        || xDictFlag > 1)
        return false;

    const bool hasRgb = rgb >= 0 && rgb <= 0xFFFFFF;
    std::uint16_t index = colorIndex;
    std::int32_t rgb24 = -1;
    switch (colorMethod) {
    case dwgColor::BYLAYER:
        index = 256;
        break;
    case dwgColor::BYBLOCK:
        index = 0;
        break;
    case dwgColor::RGB:
        if (!hasRgb)
            return false;
        rgb24 = rgb;
        break;
    case dwgColor::ACIS:
        if (index > 255)
            return false;
        break;
    default:
        // Metadata created by older callers may not set colorMethod. Infer
        // the canonical CMC method from the values that are present.
        if (hasRgb) {
            rgb24 = rgb;
        } else if (index == 0) {
            index = 0;
        } else if (index >= 256) {
            index = 256;
        } else {
            // The index-only CMC encoder uses the same 1..255 ACI range.
            if (index > 255)
                return false;
        }
        break;
    }

    dwgBufferW *sb = (strBuf != nullptr && version > DRW::AC1018)
        ? strBuf : buf;
    dwgBufferW *hb = (handleBuf != nullptr && version > DRW::AC1014)
        ? handleBuf : buf;
    buf->putCmColor(version, index, rgb24, name, bookName, sb);
    putCommonObjectHandlePrefix(hb, static_cast<std::uint32_t>(parentHandle),
                                numReactors, xDictFlag, &reactorHandles,
                                xDictHandle);
    return buf->isGood() && sb->isGood() && hb->isGood();
}

bool DRW_DimensionAssociation::encodeDwg(
    DRW::Version version, dwgBufferW *buf, dwgBufferW *strBuf,
    dwgBufferW *handleBuf) const {
    // DIMASSOC is introduced with the R2007 custom-class set. The local
    // metadata model retains four associativity slots; reject source flags
    // that require slots or sub-record data the model cannot represent.
    if (buf == nullptr || version < DRW::AC1021
        || (m_associativityFlags & ~0x0Fu) != 0
        || m_osnapRefs.size() > 4
        || m_hasUnrepresentableDetail
        || reactorHandles.size() > dwgSafety::MaxReactorCount
        || extensionDictionaryFlag() > 1)
        return false;

    std::uint32_t activeSlots = 0;
    for (std::uint32_t flag = 1; flag <= 8; flag <<= 1) {
        if ((m_associativityFlags & flag) != 0)
            ++activeSlots;
    }
    if (activeSlots != m_osnapRefs.size())
        return false;

    dwgBufferW *stringBuf = strBuf != nullptr ? strBuf : buf;
    dwgBufferW *handles = handleBuf != nullptr ? handleBuf : buf;
    buf->putBitLong(static_cast<std::int32_t>(m_associativityFlags));
    buf->putBit(m_isTransSpace ? 1 : 0);
    buf->putRawChar8(m_rotatedDimensionType);

    std::size_t refIndex = 0;
    for (std::uint32_t flag = 1; flag <= 8; flag <<= 1) {
        if ((m_associativityFlags & flag) == 0)
            continue;
        const DRW_DimensionAssociationOsnapRef& ref = m_osnapRefs[refIndex++];
        if (ref.m_objectOsnapType != 0)
            return false;
        stringBuf->putVariableText(version, ref.m_className);
        buf->putRawChar8(ref.m_objectOsnapType);

        const std::uint32_t xrefCount = ref.m_objectHandle != 0 ? 1 : 0;
        buf->putBitLong(static_cast<std::int32_t>(xrefCount));
        buf->putBitDouble(0.0); // osnap_dist
        buf->put3BitDouble(DRW_Coord{}); // osnap_pt
        buf->putBit(0); // has_lastpt_ref
    }

    putCommonObjectHandlePrefix(
        handles, static_cast<std::uint32_t>(parentHandle),
        static_cast<std::int32_t>(reactorHandles.size()),
        extensionDictionaryFlag(), &reactorHandles, xDictHandle);
    handles->putHandle(makeRefW(
        m_dimensionHandle, DRW::DwgSoftPointer));
    refIndex = 0;
    for (std::uint32_t flag = 1; flag <= 8; flag <<= 1) {
        if ((m_associativityFlags & flag) == 0)
            continue;
        const auto& ref = m_osnapRefs[refIndex++];
        if (ref.m_objectHandle != 0)
            handles->putHandle(makeRefW(
                ref.m_objectHandle, DRW::DwgSoftPointer));
    }
    return buf->isGood() && stringBuf->isGood() && handles->isGood();
}

bool DRW_EvaluationGraph::encodeDwg(
    DRW::Version version, dwgBufferW *buf, dwgBufferW * /*strBuf*/,
    dwgBufferW *handleBuf) const {
    if (buf == nullptr || version < DRW::AC1021
        || m_nodes.size() > kMaxEntries || m_edges.size() > kMaxEntries
        || reactorHandles.size() > dwgSafety::MaxReactorCount
        || extensionDictionaryFlag() > 1)
        return false;

    dwgBufferW *handles = handleBuf != nullptr ? handleBuf : buf;
    buf->putBitLong(m_value96);
    buf->putBitLong(m_value97);
    buf->putBitLong(static_cast<std::int32_t>(m_nodes.size()));
    for (const DRW_EvaluationGraphNode& node : m_nodes) {
        buf->putBitLong(node.m_index);
        buf->putBitLong(node.m_flags);
        buf->putBitLong(node.m_nextNodeIndex);
        buf->putBitLong(node.m_data1);
        buf->putBitLong(node.m_data2);
        buf->putBitLong(node.m_data3);
        buf->putBitLong(node.m_data4);
    }
    buf->putBitLong(static_cast<std::int32_t>(m_edges.size()));
    for (const DRW_EvaluationGraphEdge& edge : m_edges) {
        buf->putBitLong(edge.m_value92);
        buf->putBitLong(edge.m_value93);
        buf->putBitLong(edge.m_value94);
        buf->putBitLong(edge.m_value91a);
        buf->putBitLong(edge.m_value91b);
        buf->putBitLong(edge.m_value92a);
        buf->putBitLong(edge.m_value92b);
        buf->putBitLong(edge.m_value92c);
        buf->putBitLong(edge.m_value92d);
        buf->putBitLong(edge.m_value92e);
    }

    putCommonObjectHandlePrefix(
        handles, static_cast<std::uint32_t>(parentHandle),
        static_cast<std::int32_t>(reactorHandles.size()),
        extensionDictionaryFlag(), &reactorHandles, xDictHandle);
    for (const DRW_EvaluationGraphNode& node : m_nodes)
        handles->putHandle(makeRefW(
            node.m_expressionHandle, DRW::DwgSoftPointer));
    return buf->isGood() && handles->isGood();
}
